window.COURSE={"id": "rehearsal_keys_en", "title": "Сопротивление, пористость и вода пласта по каротажу", "book": "Keys W. S., MacCary L. M. Application of Borehole Geophysics to Water-Resources Investigations. USGS TWRI 2-E1, 1971, pp. 4–9", "generated_by": "claude_code/sonnet", "parts": [{"title": "Что даёт каротаж и почему его трудно читать", "nodes": ["keys.log_and_rock", "keys.ambiguous_response", "keys.empirical_and_borehole"]}, {"title": "Пористость и электрическое сопротивление: основы", "nodes": ["keys.porosity_basics", "keys.resistivity_unit", "keys.rock_resistivity"]}, {"title": "Виды пористости и водоотдача", "nodes": ["keys.total_effective_porosity", "keys.porosity_measurement_pitfalls", "keys.primary_secondary_porosity", "keys.specific_yield"]}, {"title": "Сопротивление воды и формационный фактор", "nodes": ["keys.saturated_true_resistivity", "keys.formation_factor", "keys.fluid_conductivity_chart", "keys.nacl_equivalent", "keys.aquifer_salinity_chart"]}, {"title": "Проницаемость и размер зёрен", "nodes": ["keys.permeability_definition", "keys.permeability_from_logs", "keys.permeability_limits", "keys.grain_size"]}, {"title": "Вода в стволе скважины и в пласте", "nodes": ["keys.borehole_vs_formation_water", "keys.salinity_log_corrections"]}, {"title": "Каротаж на практике", "nodes": ["keys.log_selection_rock", "keys.log_selection_water_well", "keys.logging_program_steps", "keys.cost_and_training"]}], "steps": [{"title": "Каротаж измеряет отклик, по которому выводят свойства пород и воды", "short_title": "Что узнают по каротажу", "why_here": {"text": "Отправная точка: вводит предмет главы и базовые слова. На неё опираются все следующие шаги о свойствах пород и флюидов.", "by_model": true}, "difficulty": {"primary": "И", "secondary": "П"}, "threshold": true, "pages": [12, 13], "misconception": {"ref": "misc.log_is_rock", "text": "Каротажная кривая — не сама порода. Это отклик прибора, на который влияют характеристики пород, флюидов в них и скважины. Свойства породы по нему нужно истолковывать.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход — отклик приборов геофизического каротажа, зависящий от пород, флюидов и скважины. Выход — параметры, измеренные прямо или полученные интерпретацией. В гидрогеологии это прежде всего литология, геометрия водоносных систем и качество воды.", "by_model": true}, "breaks": {"text": "Показание нельзя считать прямым значением одного свойства породы: на отклик влияет большинство характеристик пород, флюидов и скважины. Правильное истолкование требует знать принципы отклика приборов и взаимосвязь литологических параметров.", "by_model": true}, "hypotheses": [{"text": "В наборе данных полезно хранить рядом с кривыми сведения о скважине и флюидах, чтобы учитывать их влияние на отклик.", "by_model": true, "hypothesis": true}, {"text": "Одинаковые изменения кривой могут возникать по разным причинам, поэтому совместный разбор нескольких кривых может уменьшить неоднозначность.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это похоже на диагностику сервера по метрикам. Задержка ответа зависит от нагрузки, сети и настроек сразу. Метрика измерена, а причину выводят, зная, как устроена система.", "breaks_where": "В ИТ часто можно открыть код, конфигурацию или поставить дополнительный счётчик. Породу вокруг скважины так свободно не проверить, а отклик определяется физикой прибора и среды.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": null, "worked_examples": [], "book_tasks": [], "terms_introduced": ["геофизический каротаж (geophysical logging)", "литология (lithology)", "водоносный пласт (aquifer)", "матрица породы (rock matrix)", "флюид (fluid)"], "links": [{"type": "refutes_misconception", "target": "misc.log_is_rock"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Большинство характеристик горных пород, содержащихся в них флюидов (fluid) и скважины влияет на отклик приборов геофизического каротажа (geophysical logging).", "kind": "observation", "page_pdf": 12, "unit_id": "p012.08", "quote": "Most characteristics of rocks, the fluids they contain, and the borehole have an effect", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Речь о влиянии на отклик приборов геофизического каротажа.", "quote": "on the response of geophysical-logging instruments."}], "id": "keys.log_and_rock#c1"}, {"page_print": null, "text": "Табл. 1 — это упрощённая сводка параметров, которые можно измерить прямо или получить интерпретацией общедоступных геофизических каротажных диаграмм.", "kind": "observation", "page_pdf": 13, "unit_id": "p013.01", "quote": "Table 1 is a simplified tabulation of parameters that can be measured directly or interpreted from commonly available geophysical logs.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.log_and_rock#c2"}, {"page_print": null, "text": "На время написания книги одно из самых распространённых применений каротажа в гидрогеологии подземных вод — определение литологии (lithology) и геометрии систем водоносных пластов (aquifer).", "kind": "observation", "page_pdf": 13, "unit_id": "p013.01", "quote": "The most widespread uses of logs in ground-water hydrology at the present time are to define the lithology and geometry of aquifer systems and to estimate the quality of contained water.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.log_and_rock#c3"}, {"page_print": null, "text": "Другое из самых распространённых на время написания книги применений каротажа в гидрогеологии подземных вод — оценка качества воды, содержащейся в водоносных системах.", "kind": "observation", "page_pdf": 13, "unit_id": "p013.01", "quote": "at the present time are to define the lithology and geometry of aquifer systems and to estimate the quality of contained water.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.log_and_rock#c4"}, {"page_print": null, "text": "Чтобы правильно истолковать одну геофизическую каротажную диаграмму или их набор, нужно понимать основные принципы отклика приборов на характеристики матрицы породы (rock matrix).", "kind": "inference", "page_pdf": 13, "unit_id": "p013.01", "quote": "In order to properly interpret one log or a set of geophysical logs, the basic principles governing the response of logging devices to characteristics of the rock matrix must be understood", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.log_and_rock#c5"}, {"page_print": null, "text": "Для правильного истолкования одной каротажной диаграммы или набора диаграмм нужно также понимать взаимосвязь литологических параметров.", "kind": "inference", "page_pdf": 13, "unit_id": "p013.01", "quote": "must be understood, as well as the interrelation among lithologic parameters.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Условие относится к правильному истолкованию одной диаграммы или набора геофизических диаграмм.", "quote": "In order to properly interpret one log or a set of geophysical logs"}], "id": "keys.log_and_rock#c6"}, {"page_print": null, "text": "Литологические параметры, описанные в этом разделе, — те, что представляют главный интерес для гидрогеологов, изучающих подземные воды.", "kind": "observation", "page_pdf": 13, "unit_id": "p013.01", "quote": "The lithologic parameters described in this section are those of principal interest to ground-water hydrologists", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.log_and_rock#c7"}, {"page_print": null, "text": "Описанные в разделе литологические параметры дальше используются по всему техническому руководству без дополнительных определений.", "kind": "assumption", "page_pdf": 13, "unit_id": "p013.01", "quote": "and they will be used throughout this technical manual without further definition.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.log_and_rock#c8"}], "id": "keys.log_and_rock", "order": 1, "minutes": 3, "essence": "Показания каротажа зависят сразу от пород, содержащихся в них жидкостей и газов и самой скважины. Чтобы верно их читать, нужно понимать реакцию приборов на породу и связи её свойств. В гидрогеологии по каротажу чаще всего изучали состав и форму водоносных пластов и качество воды.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Прибор в скважине регистрирует отклик, то есть показание, возникающее под действием окружающей среды. Эту среду образуют породы, флюиды в них и сама скважина. Флюид — это жидкость или газ, например вода в порах породы.", "pages": [12, 13]}, {"text": "Большинство характеристик всех трёх участников сказывается на показаниях. Значит, между показанием и нужным свойством стоит этап истолкования. Часть параметров, по словам авторов, можно измерить прямо, а часть получают интерпретацией каротажных диаграмм.", "pages": [13]}, {"text": "Чтобы пройти от показания к свойству, нужны два вида знаний. Первый — основные принципы отклика приборов на характеристики матрицы породы (rock matrix), то есть её твёрдой части. Второй — взаимосвязь литологических параметров, то есть связанных с самой породой свойств.", "pages": [13]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "В гидрогеологии подземных вод на время написания книги у каротажа было два самых распространённых применения. Первое — определить литологию (lithology) и геометрию систем водоносных пластов. Литология — это тип и состав пород.", "pages": [13]}, {"text": "Водоносный пласт (aquifer) — это порода, которая содержит воду и может её отдавать. Геометрия — это форма и положение таких тел под землёй. Второе применение — оценить качество воды, содержащейся в этих пластах.", "pages": [13]}, {"text": "Авторы приводят табл. 1 как упрощённую сводку параметров, доступных по обычным видам каротажа. Одну диаграмму или набор диаграмм следует истолковывать, понимая принципы работы приборов и связи между свойствами пород.", "pages": [13]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Авторы говорят о большинстве характеристик пород, флюидов и скважины, а не обо всех. Табл. 1 названа упрощённой и охватывает параметры по общедоступным видам каротажа.", "pages": [12, 13]}, {"text": "Перечень самых распространённых применений относится к гидрогеологии подземных вод и ко времени написания книги. Он не означает, что других применений нет.", "pages": [13]}]}], "deeper": [{"text": "Литологические параметры, которые авторы разбирают дальше, отобраны по интересу для гидрогеологов, изучающих подземные воды. Авторы предупреждают, что в остальной части руководства будут пользоваться этими понятиями без повторных определений.", "pages": [13]}], "glossary": [{"term": "геофизический каротаж (geophysical logging)", "definition": "Измерения приборами в скважине. По их откликам определяют свойства пород, флюидов и самой скважины."}, {"term": "литология (lithology)", "definition": "Тип и состав горных пород: из чего сложен тот или иной интервал разреза."}, {"term": "водоносный пласт (aquifer)", "definition": "Порода или толща пород, которая содержит воду и способна её отдавать."}, {"term": "матрица породы (rock matrix)", "definition": "Твёрдая часть породы, в отличие от пустот и заполняющих их флюидов."}, {"term": "флюид (fluid)", "definition": "Подвижная среда, жидкость или газ, например вода в порах породы или жидкость в скважине."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [], "numbers": [], "formulas": [], "tables": [], "videos": [], "interactive": null, "narration": null}, {"title": "Отклик каротажа неоднозначен, поэтому интерпретация требует знания теории и местной геологии", "short_title": "Один сигнал, разные причины", "why_here": {"text": "Опирается на идею косвенного измерения из первого шага. Объясняет, почему дальше все зависимости даются как приближённые.", "by_model": true}, "difficulty": {"primary": "Н", "secondary": "И"}, "threshold": true, "pages": [12], "misconception": {"ref": "misc.log_is_rock", "text": "Каротажная кривая — не сама порода, а косвенное измерение. Одно и то же отклонение в разных районах может быть вызвано разной литологией.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход — записанный отклик каротажа, например отклонение кривой. Искомый выход — литология. Связь между ними у большинства диаграмм не однозначна. Для привязки отклика служат образцы, керн, модели и экспериментально полученные уравнения, а также сведения о геологической обстановке.", "by_model": false}, "breaks": {"text": "Правило «такое отклонение — такая литология», верное в одном районе, может не работать в другом. Теоретическое уравнение без эмпирических данных не даёт определить входящие в него неизвестные.", "by_model": true}, "hypotheses": [{"text": "В наборе данных полезно хранить рядом с кривыми район и геологическую обстановку, чтобы не смешивать разные связи отклика с породой.", "by_model": true, "hypothesis": true}, {"text": "Модель, обученную распознавать литологию в одном районе, стоит отдельно проверять на скважинах другого района.", "by_model": true, "hypothesis": true}, {"text": "Метки литологии по керну и образцам могут служить опорной выборкой для местной эмпирической связи.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это похоже на одно сообщение «timeout» в разных системах. В одной его причина — сеть, в другой — медленная база данных. Чтобы поставить диагноз, нужно знать устройство механизма и особенности конкретного окружения.", "breaks_where": "В ИТ часто можно воспроизвести сбой и посмотреть код или подробные логи. Породу вокруг скважины так полно не осмотреть: образцы и керн дают лишь опору для истолкования.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Каротажные диаграммы, образцы, керн, модели, уравнения и сведения о геологической обстановке.", "manual_steps": "Сопоставить отклик с местными опытными данными, учесть теорию метода и выбрать объяснение отклонения.", "judgment_points": "Какая литология вызывает отклонение в данном районе; можно ли полагаться на уравнение или на прямую эмпирическую связь.", "time": "в главе не указано", "typical_errors": "Перенести истолкование отклонения из одного района в другой без проверки; применить уравнение без эмпирических данных.", "by_model": true}, "decision_on_data": {"features": ["Записанное отклонение каротажной кривой", "Район и геологическая обстановка", "Местные образцы, керн, модели или экспериментально полученные уравнения", "Теория применённого метода каротажа"], "rule": "Не определять литологию по одному отклонению. Сопоставить его с местными опытными данными и сведениями об обстановке с учётом теории метода.", "conclusion": "Вывод о литологии обоснован для той обстановки, где отклик с ней сопоставлен.", "counterexample": "Такое же отклонение в другом месте может быть вызвано другой литологией, и перенесённый вывод окажется неверным."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["каротажная диаграмма (log)", "интерпретация каротажа (log interpretation)", "керн (core)", "эмпирический метод (empirical method)"], "links": [{"type": "prerequisite", "target": "keys.log_and_rock"}, {"type": "refutes_misconception", "target": "misc.log_is_rock"}], "needs_scan": [], "claims": [{"page_print": null, "text": "По мнению авторов, одна из фундаментальных проблем применения геофизических каротажных диаграмм такова: интерпретация многих из них — скорее искусство, чем наука.", "kind": "inference", "page_pdf": 12, "unit_id": "p012.03", "quote": "One fundamental problem in the application of geophysical logs is that the interpretation of many logs is more of an art than a science.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.ambiguous_response#c1"}, {"page_print": null, "text": "Многочисленные факторы окружающей обстановки, вызывающие отклик каротажа, трудно анализировать количественно.", "kind": "observation", "page_pdf": 12, "unit_id": "p012.03", "quote": "The numerous environmental factors causing log response are difficult to analyze quantitatively.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.ambiguous_response#c2"}, {"page_print": null, "text": "Даже когда есть теоретически выведенные уравнения, для определения неизвестных в них нужны эмпирические (опытные) данные.", "kind": "observation", "page_pdf": 12, "unit_id": "p012.03", "quote": "Even when theoretically derived equations are available, empirical data are needed to determine the unknowns in the equation", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.ambiguous_response#c3"}, {"page_print": null, "text": "По мнению авторов, из-за потребности в эмпирических данных для уравнений прямые эмпирические методы могут быть надёжнее.", "kind": "inference", "page_pdf": 12, "unit_id": "p012.03", "quote": "empirical data are needed to determine the unknowns in the equation; therefore, direct empirical methods may be more reliable.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.ambiguous_response#c4"}, {"page_print": null, "text": "Эмпирические методы (empirical methods) основаны на связи отклика каротажа с образцами, керном (core), моделями или экспериментально полученными уравнениями.", "kind": "observation", "page_pdf": 12, "unit_id": "p012.03", "quote": "Empirical methods are based on the relationship of log response to samples, core, models, or experimentally derived equations.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.ambiguous_response#c5"}, {"page_print": null, "text": "У большинства геофизических каротажных диаграмм нет однозначного отклика.", "kind": "observation", "page_pdf": 12, "unit_id": "p012.03", "quote": "Most geophysical logs do not have a unique response", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.ambiguous_response#c6"}, {"page_print": null, "text": "Определённое записанное отклонение кривой может быть вызвано одной литологией в одном районе и другой литологией в другом месте.", "kind": "observation", "page_pdf": 12, "unit_id": "p012.03", "quote": "that is, a certain recorded deflection may be due to one lithology in one area and due to another lithology elsewhere.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.ambiguous_response#c7"}, {"page_print": null, "text": "Поскольку отклик неоднозначен, для руководства интерпретацией каротажа необходимы предварительные сведения и опыт по каждой геологической обстановке.", "kind": "inference", "page_pdf": 12, "unit_id": "p012.03", "quote": "For this reason, background information and experience in each geologic environment is essential to guide log interpretation.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.ambiguous_response#c8"}, {"page_print": null, "text": "Интерпретация должна также опираться на твёрдое знание теории каждого метода каротажа.", "kind": "inference", "page_pdf": 12, "unit_id": "p012.03", "quote": "Interpretation must also be based on sound knowledge of the theory of each logging technique.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.ambiguous_response#c9"}], "id": "keys.ambiguous_response", "order": 2, "minutes": 3, "essence": "Одно и то же отклонение каротажной кривой в разных районах может означать разные породы. Поэтому нужны знание теории каждого метода, сведения о местной геологии и опыт. Даже теоретические уравнения требуют опытных данных, чтобы определить в них неизвестные.", "how": [{"title": "Механизм", "by_model": false, "paragraphs": [{"text": "Каротажная диаграмма (log) — это запись отклика прибора в скважине. Интерпретация каротажа (log interpretation) — это переход от записи к выводам о породах. На отклик влияют многочисленные факторы окружающей обстановки.", "pages": [12]}, {"text": "Их трудно разобрать количественно, то есть выразить и разделить числами. Поэтому, по мнению авторов, интерпретация многих диаграмм — скорее искусство, чем наука. Даже теоретически выведенное уравнение не решает задачу само.", "pages": [12]}, {"text": "Чтобы определить неизвестные в нём, нужны эмпирические, то есть опытные, данные. Отсюда вывод авторов: прямые эмпирические методы могут быть надёжнее. У большинства геофизических диаграмм нет однозначного отклика.", "pages": [12]}, {"text": "Отклонение — это изменение записанной кривой. Одинаковое отклонение в разных районах может быть вызвано разной литологией, то есть разным характером породы.", "pages": [12]}]}, {"title": "Как работает специалист", "by_model": false, "paragraphs": [{"text": "Эмпирический метод (empirical method) связывает отклик каротажа с тем, что известно из опыта. Опорой служат образцы, керн, модели или экспериментально полученные уравнения. Керн (core) — это образец породы, извлечённый из скважины при бурении.", "pages": [12]}, {"text": "Чтобы направлять интерпретацию, в каждой геологической обстановке необходимы предварительные сведения о ней и опыт. Кроме того, интерпретация должна опираться на твёрдое знание теории каждого метода каротажа.", "pages": [12]}]}, {"title": "Нюансы", "by_model": false, "paragraphs": [{"text": "Оценка «скорее искусство, чем наука» дана авторами для многих диаграмм, а не для всех. Отсутствие однозначного отклика отнесено к большинству геофизических диаграмм. О надёжности эмпирических методов сказано осторожно: они могут быть надёжнее.", "pages": [12]}, {"text": "Теорию авторы не отвергают: её знание названо обязательной основой интерпретации.", "pages": [12]}]}], "deeper": [{"text": "Здесь есть две разные трудности. Первая: факторы, формирующие отклик, трудно оценить количественно. Вторая: одинаковая запись может возникать из-за разной литологии. Местные опытные данные помогают привязать отклик к породам конкретной обстановки.", "pages": [12]}], "glossary": [{"term": "каротажная диаграмма (log)", "definition": "Запись отклика прибора, измеряющего в скважине; по ней делают выводы о породах и флюидах."}, {"term": "интерпретация каротажа (log interpretation)", "definition": "Истолкование каротажных диаграмм: переход от записанного отклика к выводам о породах и их свойствах."}, {"term": "керн (core)", "definition": "Образец породы, извлечённый из скважины при бурении; с ним можно сопоставлять отклик каротажа."}, {"term": "эмпирический метод (empirical method)", "definition": "Способ истолкования, основанный на связи отклика каротажа с образцами, керном, моделями или экспериментально полученными уравнениями."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [], "numbers": [], "formulas": [], "tables": [], "videos": [], "interactive": null, "narration": null}, {"title": "Однозначных правил нет: влияние скважины приходится распознавать и исправлять", "short_title": "Помехи скважины и исключения из правил", "why_here": {"text": "Продолжает разговор о неоднозначности примером с глиной и влиянием ствола. Готовит к поправкам за свойства жидкости в скважине.", "by_model": true}, "difficulty": {"primary": "Н", "secondary": "И"}, "threshold": false, "pages": [12], "misconception": {"ref": "misc.gr_measures_clay", "text": "Гамма-каротаж не измеряет глинистость напрямую. Он фиксирует интенсивность гамма-излучения, а глина не всегда даёт более высокие показания, чем соседние пески.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Кривую естественного гамма-каротажа нельзя читать по однозначному правилу: глина не всегда показывает большую интенсивность, чем соседние пески. Посторонние влияния на отклик, в том числе параметры скважины, нужно распознать и исправить, обычно эмпирически.", "by_model": false}, "breaks": {"text": "Правило «выше гамма-интенсивность — значит глина» ломается там, где глина не излучает сильнее соседних песков. Сравнение откликов может вводить в заблуждение и тогда, когда влияние скважины не распознано и не исправлено.", "by_model": true}, "hypotheses": [{"text": "Пески с калиевыми полевыми шпатами, слюдами или тяжёлыми радиоактивными минералами могут давать высокие гамма-показания, сравнимые с глиной или выше.", "by_model": true, "hypothesis": true}, {"text": "Кривую диаметра скважины (кавернограмму) полезно просматривать рядом с гамма-кривой: расширения ствола могут менять отклик без изменения породы.", "by_model": true, "hypothesis": true}, {"text": "В наборе данных полезно хранить рядом с кривыми параметры скважины и отметку, внесены ли поправки.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Время ответа сервиса, измеренное на клиенте, включает не только работу сервера, но и влияние сети. Прежде чем судить о сервере, это влияние надо распознать и учесть. Так и в отклике каротажа к сигналу породы примешивается влияние скважины.", "breaks_where": "В ИТ сеть часто можно измерить отдельно или повторить запрос в чистой среде. Скважину из каротажного измерения так просто не убрать, и поправки обычно опираются на эмпирические зависимости.", "by_model": true}, "now_practice": {"text": "Сейчас вместе с обычным гамма-каротажем применяют спектрометрический, который различает калий, уран и торий. Он помогает отличить глину от калиевых песчаников и урановых аномалий.", "by_model": true}, "inefficiency_lens": {"inputs": "Каротажные диаграммы, параметры скважины, знания о местной геологии.", "manual_steps": "Распознать посторонние влияния на отклик, внести поправки (обычно эмпирические), затем толковать породу.", "judgment_points": "Решить, отражает ли изменение кривой породу или влияние скважины. Решить, применимо ли в данном разрезе правило о высоких гамма-показаниях глины.", "time": "в главе не указано", "typical_errors": "Считать глиной всё, что излучает сильнее соседних пород, или толковать кривую без поправок за скважину.", "by_model": true}, "decision_on_data": {"features": ["Интенсивность естественного гамма-излучения в интервале по сравнению с соседними песками", "Наличие посторонних влияний, например параметров скважины"], "rule": "Сначала распознать и исправить влияние скважины. Затем не делать вывод о глине только по соотношению гамма-интенсивностей, без проверки местными данными.", "conclusion": "Разница гамма-показаний служит признаком для проверки, а не однозначным определением породы.", "counterexample": "Глина не всегда показывает более высокую гамма-интенсивность, чем соседние пески, поэтому по такому правилу её можно пропустить."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["естественный гамма-каротаж (natural-gamma log)", "параметры скважины (borehole parameters)"], "links": [{"type": "prerequisite", "target": "keys.log_and_rock"}, {"type": "prerequisite", "target": "keys.ambiguous_response"}, {"type": "refutes_misconception", "target": "misc.gr_measures_clay"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Нет такого текста (учебника или руководства), который давал бы однозначные правила интерпретации каротажа.", "kind": "inference", "page_pdf": 12, "unit_id": "p012.04", "quote": "There is no text that gives unambiguous rules for log interpretation.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.empirical_and_borehole#c1"}, {"page_print": null, "text": "Например, глина не всегда показывает более высокую интенсивность на естественном гамма-каротаже (natural-gamma log), чем соседние пески. Район и породы, для которых это отмечено, автор здесь не называет.", "kind": "observation", "page_pdf": 12, "unit_id": "p012.04", "quote": "For example, clay does not always exhibit a higher natural-gamma intensity than adjacent sands.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.empirical_and_borehole#c2"}, {"page_print": null, "text": "Посторонние влияния на каротаж, такие как параметры скважины (borehole parameters), необходимо распознавать и исправлять, обычно эмпирическими методами.", "kind": "inference", "page_pdf": 12, "unit_id": "p012.04", "quote": "Furthermore, extraneous effects, such as borehole parameters, must be recognized and corrected, generally by empirical methods.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.empirical_and_borehole#c3"}, {"page_print": null, "text": "Эти ограничения не помешали почти повсеместному применению каротажа скважин в поисках и разведке нефти.", "kind": "observation", "page_pdf": 12, "unit_id": "p012.04", "quote": "These limitations have not prevented the nearly universal application of well logging to petroleum exploration;", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.empirical_and_borehole#c4"}, {"page_print": null, "text": "Почти каждую скважину, пробуренную на нефть в любой точке мира, исследуют каротажем (на время написания книги).", "kind": "observation", "page_pdf": 12, "unit_id": "p012.04", "quote": "almost every well drilled for oil anywhere in the world is logged.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.empirical_and_borehole#c5"}, {"page_print": null, "text": "Гидрогеологи, изучающие подземные воды, и геологи-нефтяники ищут одни и те же основные сведения о залегании, характере и движении флюидов под землёй.", "kind": "observation", "page_pdf": 12, "unit_id": "p012.04", "quote": "Ground-water hydrologists and petroleum geologists are seeking the same basic information on the occurrence, character, and movement of fluids underground", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.empirical_and_borehole#c6"}, {"page_print": null, "text": "Эти сведения о флюидах нужны специалистам обеих областей, чтобы направлять отбор флюидов из недр или их закачку.", "kind": "observation", "page_pdf": 12, "unit_id": "p012.04", "quote": "in order to guide subsurface fluid withdrawal or injection.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.empirical_and_borehole#c7"}], "id": "keys.empirical_and_borehole", "order": 3, "minutes": 3, "essence": "Однозначных правил чтения каротажа нет ни в одном учебнике или руководстве. Влияние самой скважины нужно распознавать и исправлять, обычно по опытным зависимостям. Несмотря на это, на время написания книги каротировали почти каждую нефтяную скважину в мире.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Естественный гамма-каротаж (natural-gamma log) записывает интенсивность собственного гамма-излучения пород вдоль ствола скважины. Часто хочется считать, что повышенная интенсивность означает глину. Автор показывает, что это не закон: глина не всегда излучает сильнее соседних песков.", "pages": [12]}, {"text": "Есть и вторая трудность. На отклик прибора действует не только порода. Мешают посторонние влияния, в частности параметры скважины (borehole parameters), то есть свойства самого ствола и его окружения при измерении.", "pages": [12]}, {"text": "Поэтому такое влияние сначала надо заметить, а затем внести поправку.", "pages": [12]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Не переносите готовое правило «глина даёт более высокие показания, чем пески» на любой разрез без проверки. Прежде чем делать вывод о породе, спросите, не исказила ли отклик сама скважина. Обнаруженное влияние нужно исправить.", "pages": [12]}, {"text": "Обычно это делают эмпирическим методом (empirical method), то есть опираясь на опытные зависимости. Ограничения не делают каротаж бесполезным. Автор пишет, что каротируют почти каждую нефтяную скважину в мире.", "pages": [12]}, {"text": "Специалистам по подземным водам и геологам-нефтяникам нужны одни и те же основные сведения о флюидах под землёй.", "pages": [12]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Пример с глиной сформулирован осторожно: «не всегда». Из него не следует, что глина обычно излучает слабее песков или что гамма-каротаж не годится для оценки глины. Для каких районов и пород встречается такое исключение, автор здесь не называет.", "pages": [12]}, {"text": "Оговорка «обычно» относится к способу исправления: поправки вносят эмпирическими методами, но не обязательно только ими. Слова о почти всеобщем применении каротажа относятся к нефтяной отрасли времени написания книги. На водозаборные скважины это утверждение не распространяется.", "pages": [12]}]}], "deeper": [{"text": "Автор сближает две области: гидрогеологию подземных вод и нефтяную геологию. Обеих интересует, где находятся флюиды, каковы они и как движутся. Эти сведения нужны, чтобы управлять отбором флюидов из недр или их закачкой.", "pages": [12]}], "glossary": [{"term": "естественный гамма-каротаж (natural-gamma log)", "definition": "Каротаж, который записывает интенсивность собственного гамма-излучения пород вдоль ствола скважины."}, {"term": "параметры скважины (borehole parameters)", "definition": "Свойства самого ствола и условий в нём, которые могут искажать отклик прибора помимо свойств породы."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [{"text": "Распознайте посторонние влияния на показания каротажа, например влияние параметров скважины.", "pages": [12], "claim_id": "keys.empirical_and_borehole#c3"}, {"text": "Исправьте показания с учётом этих влияний, обычно опираясь на опытные зависимости.", "pages": [12], "claim_id": "keys.empirical_and_borehole#c3"}], "numbers": [], "formulas": [], "tables": [], "videos": [], "interactive": null, "narration": null}, {"title": "Пористость — доля объёма пустот в общем объёме породы", "short_title": "Что такое пористость", "why_here": {"text": "Первый литологический параметр: без него не объяснить сопротивление породы. Дальше разбираются виды пористости и связь с проницаемостью.", "by_model": true}, "difficulty": {"primary": "И", "secondary": "Н"}, "threshold": true, "pages": [15], "misconception": {"ref": "misc.porosity_eq_perm", "text": "Пористость — это доля объёма пустот, а проницаемость — способность породы пропускать жидкость. Это разные свойства. Автор говорит лишь о местной связи между ними, а не об их тождестве.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Входом для оценки пористости могут служить данные гамма-гамма, нейтронного, акустического и электрического каротажа. Выход — пористость φ, то есть отношение объёма пустот к общему объёму, обычно в процентах. Разные виды каротажа по-разному откликаются на общую и эффективную пористость.", "by_model": false}, "breaks": {"text": "Значение с подписью «пористость» неоднозначно, если не указано, общая она или эффективная. Во многих породах эти два вида непросто различить. Связь пористости с проницаемостью названа местной, поэтому её нельзя без проверки переносить в другое место.", "by_model": true}, "hypotheses": [{"text": "В таблице данных полезно хранить рядом с пористостью её вид (общая, эффективная или не указан) и метод каротажа.", "by_model": true, "hypothesis": true}, {"text": "Стоит явно записывать, в чём задана пористость — в процентах или в долях единицы, чтобы не смешать значения.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Слово «пористость» без уточнения похоже на метрику «размер хранилища» без пометки, весь это объём или только доступный. Число есть, но неясно, что именно посчитано.", "breaks_where": "В ИТ оба объёма обычно можно прямо запросить у системы. В породе пористость выводят из каротажа, а общую и эффективную во многих породах непросто различить.", "by_model": true}, "now_practice": {"text": "Сейчас для оценки пористости применяют компенсированные нейтронный и плотностной приборы, причём нейтронный калибруют в единицах пористости. Акустические приборы стали широкополосными и записывают разные типы волн.", "by_model": true}, "inefficiency_lens": null, "decision_on_data": null, "worked_examples": [], "book_tasks": [], "terms_introduced": ["пористость (porosity)", "φ", "гамма-гамма-каротаж (gamma-gamma log)", "нейтронный каротаж (neutron log)", "акустический каротаж (acoustic-velocity log)", "электрический каротаж (electric log)"], "links": [{"type": "prerequisite", "target": "keys.log_and_rock"}, {"type": "prerequisite", "target": "keys.ambiguous_response"}, {"type": "refutes_misconception", "target": "misc.porosity_eq_perm"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Пористость (porosity) φ может быть получена по данным гамма-гамма-каротажа (gamma-gamma log), нейтронного (neutron), акустического (acoustic-velocity) и электрического (electric) каротажа.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.03", "quote": "Porosity $(\\phi)$ may be derived from gamma-gamma, neutron, acoustic-velocity and electric logs.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_basics#c1"}, {"page_print": null, "text": "Пористость связана с количеством воды, запасённой в горных породах.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.03", "quote": "Because porosity is related to the amount of water stored in rocks and has a local relation to permeability", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_basics#c2"}, {"page_print": null, "text": "Пористость имеет местную (local) связь с проницаемостью (permeability).", "kind": "observation", "page_pdf": 15, "unit_id": "p015.03", "quote": "porosity is related to the amount of water stored in rocks and has a local relation to permeability", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_basics#c3"}, {"page_print": null, "text": "Поскольку пористость связана с запасённой в породах водой и местно связана с проницаемостью, это важный гидрогеологический параметр.", "kind": "inference", "page_pdf": 15, "unit_id": "p015.03", "quote": "Because porosity is related to the amount of water stored in rocks and has a local relation to permeability, it is an important hydrologic parameter.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_basics#c4"}, {"page_print": null, "text": "Пористость определяют просто: это отношение объёма пустот пористой среды к её общему объёму.", "kind": "assumption", "page_pdf": 15, "unit_id": "p015.03", "quote": "Porosity is simply defined as the ratio of the void volume of a porous medium to the total volume", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_basics#c5"}, {"page_print": null, "text": "Пористость обычно выражают в процентах.", "kind": "assumption", "page_pdf": 15, "unit_id": "p015.03", "quote": "to the total volume, and is generally expressed as a percentage.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_basics#c6"}, {"page_print": null, "text": "По мнению автора, в значительной части литературы по каротажу простое определение осложняется: слово «пористость» употребляют без определения или без уточнений «общая» (total) или «эффективная» (effective).", "kind": "inference", "page_pdf": 15, "unit_id": "p015.03", "quote": "This simple definition is complicated in much of the literature on well logging by use of the word \"porosity,\" without definition or without the modifying terms \"total\" or \"effective.\"", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_basics#c7"}, {"page_print": null, "text": "Во многих породах общую пористость (total porosity) и эффективную пористость (effective porosity) непросто различить.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.03", "quote": "Further, total porosity and effective porosity are not easily distinguished in many rocks.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_basics#c8"}, {"page_print": null, "text": "Разные виды каротажа по-разному откликаются на два вида пористости — общую и эффективную.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.03", "quote": "Because various types of logs respond differently to the two types of porosity", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_basics#c9"}, {"page_print": null, "text": "По мнению автора, из-за разного отклика видов каротажа на два вида пористости необходимо вводное обсуждение этих видов.", "kind": "inference", "page_pdf": 15, "unit_id": "p015.03", "quote": "Because various types of logs respond differently to the two types of porosity, an introductory discussion is necessary.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_basics#c10"}], "id": "keys.porosity_basics", "order": 4, "minutes": 3, "essence": "Пористость — это доля объёма пустот в общем объёме породы, обычно в процентах. Она связана с запасом воды в породах, а местами и с проницаемостью. Нужно уточнять, общая это пористость или эффективная: разные виды каротажа реагируют на них по-разному.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Порода состоит не только из твёрдого вещества: в ней есть пустоты. Пористость φ показывает, какую долю общего объёма занимают эти пустоты. Пористую среду здесь можно понимать как материал с такими пустотами внутри.", "pages": [15]}, {"text": "Пористость связана с количеством воды, которую запасают породы. У неё есть и связь с проницаемостью (permeability), то есть со способностью породы пропускать жидкость. Эту вторую связь автор называет местной (local).", "pages": [15]}, {"text": "Поэтому её не следует считать общим правилом для любых пород и районов. Пористость можно получить по данным нескольких видов каротажа. Это гамма-гамма-каротаж (gamma-gamma log), нейтронный каротаж (neutron log), акустический каротаж (acoustic-velocity log) и электрический каротаж (electric log).", "pages": [15]}, {"text": "Здесь пористость выводят из каротажных данных.", "pages": [15]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Встретив слово «пористость», проверьте, определено ли оно. Выясните, идёт ли речь об общей (total) или эффективной (effective) пористости. Общая пористость учитывает все поры.", "pages": [15]}, {"text": "Эффективная учитывает только сообщающиеся поры, способные передавать жидкость. Это важно, потому что разные виды каротажа по-разному откликаются на эти два вида пористости. Значения, полученные разными методами, не стоит сравнивать, не выяснив, что за ними стоит.", "pages": [15]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Само определение пористости простое. Но в значительной части литературы по каротажу его осложняет употребление слова без пояснений. Автор отмечает, что «пористость» пишут без определения или без слов «общая» и «эффективная».", "pages": [15]}, {"text": "Есть и вторая трудность: во многих породах общую и эффективную пористость непросто различить. Поэтому автор считает нужным отдельно обсудить эти виды. Связь пористости с проницаемостью автор называет местной.", "pages": [15]}, {"text": "Конкретный район или породы для неё в этом месте не названы.", "pages": [15]}]}], "deeper": [], "glossary": [{"term": "пористость (porosity)", "definition": "Отношение объёма пустот пористой среды к её общему объёму; обычно выражается в процентах."}, {"term": "φ", "definition": "Обозначение пористости (греческая буква «фи»)."}, {"term": "гамма-гамма-каротаж (gamma-gamma log)", "definition": "Вид каротажа: прибор облучает породу гамма-лучами и регистрирует вернувшееся излучение, которое зависит от плотности. По нему можно получить пористость."}, {"term": "нейтронный каротаж (neutron log)", "definition": "Вид каротажа с источником нейтронов, отклик которого зависит в основном от содержания водорода. По нему можно получить пористость."}, {"term": "акустический каротаж (acoustic-velocity log)", "definition": "Вид каротажа, основанный на скорости прохождения звуковых волн через породу. По нему можно получить пористость."}, {"term": "электрический каротаж (electric log)", "definition": "Вид каротажа, измеряющий электрические свойства пород и содержащихся в них флюидов, например удельное сопротивление. По нему можно получить пористость."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [], "numbers": [], "formulas": [], "tables": [], "videos": [], "interactive": null, "narration": null}, {"title": "Удельное электрическое сопротивление — свойство вещества, измеряемое в ом-метрах", "short_title": "Что такое удельное сопротивление", "why_here": {"text": "Вводит основную величину электрического каротажа. Нужна для разговора о сопротивлении породы, воды и формационном факторе.", "by_model": true}, "difficulty": {"primary": "Ф", "secondary": "И"}, "threshold": true, "pages": [13], "misconception": {"ref": null, "text": "«Сопротивление породы определяется только её минеральными частицами». Оно зависит и от флюидов. В насыщенной осадочной породе важны количество флюида в порах, его солёность и связь пор между собой.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Удельное сопротивление породы — величина в ом-метрах. Для насыщенных осадочных пород она зависит от количества флюида в порах, его солёности и соединённости пор.", "by_model": true}, "breaks": {"text": "Одно значение сопротивления зависит сразу от нескольких факторов. Поэтому считать его мерой только одного из них, например количества флюида, нельзя. Объяснение через проводящую воду дано для насыщенных осадочных пород, и его не следует без проверки переносить на другие случаи.", "by_model": true}, "hypotheses": [{"text": "В таблице данных рядом с сопротивлением полезно хранить сведения о солёности воды и пористости, если они есть. Иначе причины различий между интервалами трудно разделить.", "by_model": true, "hypothesis": true}, {"text": "Перед объединением данных стоит проверить, что столбец содержит именно удельное сопротивление в Ом·м, а не сопротивление в омах или электропроводность.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Удельное сопротивление похоже на удельную метрику, например цену за гигабайт. Она позволяет сравнивать объекты независимо от их общего объёма. Сопротивление в омах похоже на общий счёт за конкретный объём.", "breaks_where": "Цену за гигабайт назначают как одно число тарифа. Удельное сопротивление породы складывается физически: из свойств породы, количества и солёности флюида и связи пор. Кроме того, сопротивление образца зависит не просто от объёма, а от его длины и сечения.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": null, "worked_examples": [], "book_tasks": [], "terms_introduced": ["удельное электрическое сопротивление (electrical resistivity)", "ом-метр (ohm-meter)"], "links": [{"type": "prerequisite", "target": "keys.porosity_basics"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Удельное электрическое сопротивление (electrical resistivity) породы зависит от физических свойств самой породы и содержащихся в ней флюидов.", "kind": "observation", "page_pdf": 13, "unit_id": "p013.03", "quote": "The electrical resistivity of a rock depends on physical properties of the rock and the fluids it contains.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.resistivity_unit#c1"}, {"page_print": null, "text": "Большинство осадочных пород сложено частицами с очень высоким сопротивлением электрическому току.", "kind": "observation", "page_pdf": 13, "unit_id": "p013.03", "quote": "Most sedimentary rocks are composed of particles having a very high resistance to the flow of electrical current.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.resistivity_unit#c2"}, {"page_print": null, "text": "Когда такие осадочные породы насыщены, вода в порах проводит ток сравнительно хорошо по сравнению с частицами, или матрицей, породы.", "kind": "observation", "page_pdf": 13, "unit_id": "p013.03", "quote": "When these rocks are saturated, the water filling the pore spaces is relatively conductive compared with the rock particles or matrix.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Речь о большинстве осадочных пород, сложенных частицами с очень высоким сопротивлением.", "quote": "Most sedimentary rocks are composed of particles having a very high resistance to the flow of electrical current."}], "id": "keys.resistivity_unit#c3"}, {"page_print": null, "text": "Поэтому удельное сопротивление насыщенной осадочной породы зависит от количества флюида в порах, солёности этого флюида и того, как поры соединены между собой.", "kind": "inference", "page_pdf": 13, "unit_id": "p013.03", "quote": "The resistivity of a rock, therefore, is a function of the amount of fluid contained in the pore spaces, the salinity of that fluid, and how the pore spaces are interconnected.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Вывод опирается на случай насыщенной породы, где вода в порах сравнительно проводящая.", "quote": "When these rocks are saturated, the water filling the pore spaces is relatively conductive compared with the rock particles or matrix."}], "id": "keys.resistivity_unit#c4"}, {"page_print": null, "text": "По мнению авторов, главный фактор геометрии порового пространства — вероятно, извилистость (tortuosity).", "kind": "inference", "page_pdf": 13, "unit_id": "p013.03", "quote": "The main factor in pore geometry is probably tortuosity", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.resistivity_unit#c5"}, {"page_print": null, "text": "Извилистость определяют как квадрат отношения действительной длины пути тока к длине образца, через который течёт ток.", "kind": "assumption", "page_pdf": 13, "unit_id": "p013.03", "quote": "tortuosity, which is defined as the square of the ratio of the actual path length of the current to the length of the sample through which it flows.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.resistivity_unit#c6"}, {"page_print": null, "text": "Удельное сопротивление измеряют в ом-метрах (ohm-meter); авторы поясняют эту единицу через сопротивление куба материала с ребром один метр.", "kind": "assumption", "page_pdf": 13, "unit_id": "p013.03", "quote": "Resistivity is measured in ohm-meters, which is the resistance of a cube of material that is one meter on a side", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.resistivity_unit#c7"}, {"page_print": null, "text": "Сопротивление куба материала с ребром один метр, выраженное в омах, численно равно удельному сопротивлению в ом-метрах.", "kind": "observation", "page_pdf": 13, "unit_id": "p013.03", "quote": "the resistance of that cube, in ohms, is numerically equal to the resistivity, in ohm-meters.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Куб материала имеет ребро один метр.", "quote": "the resistance of a cube of material that is one meter on a side"}], "id": "keys.resistivity_unit#c8"}], "id": "keys.resistivity_unit", "order": 5, "minutes": 2, "essence": "Удельное электрическое сопротивление породы зависит от свойств самой породы и флюидов в ней. Вода в порах насыщенной осадочной породы проводит ток сравнительно хорошо, а частицы породы — плохо. Измеряют эту величину в ом-метрах.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Удельное электрическое сопротивление говорит о том, насколько вещество мешает электрическому току. Большинство осадочных пород сложено частицами, которые сопротивляются току очень сильно. Когда такая порода насыщена, поры заполнены водой.", "pages": [13]}, {"text": "Эта вода проводит ток сравнительно хорошо, если сравнивать её с частицами, то есть с матрицей породы. Поэтому сопротивление породы зависит от трёх вещей. Первая — сколько флюида находится в порах.", "pages": [13]}, {"text": "Вторая — солёность этого флюида, то есть содержание в нём растворённых солей. Третья — как поры соединены между собой. Про устройство порового пространства авторы говорят осторожно.", "pages": [13]}, {"text": "Главный фактор здесь, вероятно, извилистость (tortuosity). Она описывает, насколько путь тока длиннее самого образца. Формально это квадрат отношения действительной длины пути тока к длине образца, через который он течёт.", "pages": [13]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Значения удельного сопротивления записывают в ом-метрах (Ом·м). Представьте куб материала с ребром один метр. Сопротивление этого куба в омах численно равно удельному сопротивлению материала в ом-метрах.", "pages": [13]}, {"text": "Так единицу удобно себе представить.", "pages": [13]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Объяснение через проводящую воду дано для осадочных пород в насыщенном состоянии. Авторы говорят о большинстве таких пород, а не обо всех. Про извилистость сказано «вероятно»: это не установленное твёрдо утверждение.", "pages": [13]}, {"text": "Числа в омах и ом-метрах у куба совпадают, но это разные величины. Ом относится к конкретному кубу, а ом-метр — к материалу.", "pages": [13]}]}], "deeper": [{"text": "Извилистость задана как квадрат отношения длин, а не как само отношение. Числитель — действительная длина пути тока, знаменатель — длина образца.", "pages": [13]}], "glossary": [{"term": "удельное электрическое сопротивление (electrical resistivity)", "definition": "Свойство вещества мешать электрическому току, не зависящее от размеров образца; измеряется в ом-метрах."}, {"term": "ом-метр (ohm-meter)", "definition": "Единица удельного сопротивления (Ом·м). Сопротивление куба с ребром один метр в омах численно равно удельному сопротивлению материала в ом-метрах."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [], "numbers": [], "formulas": [], "tables": [], "videos": [], "interactive": null, "narration": null}, {"title": "Сопротивление породы определяют объём воды в порах, её солёность и связность пор", "short_title": "От чего зависит сопротивление породы", "why_here": {"text": "Соединяет пористость и сопротивление: ток идёт в основном по воде в порах. Открывает путь к эффективной пористости и формационному фактору.", "by_model": true}, "difficulty": {"primary": "М", "secondary": "И"}, "threshold": true, "pages": [13], "misconception": {"ref": "misc.high_res_oil", "text": "Сопротивление породы нельзя считать прямым признаком нефти. Оно зависит от свойств породы и флюидов, в частности от объёма флюида в порах, его солёности и соединения пор.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Выход — удельное сопротивление породы в ом-метрах. Среди того, что его определяет, названы количество флюида в порах, солёность этого флюида и соединение пор. Одно значение сопротивления отражает совместное действие этих факторов.", "by_model": true}, "breaks": {"text": "Объяснение о проводящей воде дано для насыщенных осадочных пород с частицами очень высокого сопротивления, каких большинство. На все породы его без проверки переносить нельзя. При частичном насыщении углеводородами, как отмечает глава, нужна поправка.", "by_model": true}, "hypotheses": [{"text": "При прочих равных больше соединённой воды в порах и выше её солёность, вероятно, означают меньшее сопротивление породы.", "by_model": true, "hypothesis": true}, {"text": "Более извилистый путь тока при прочих равных, вероятно, повышает сопротивление породы.", "by_model": true, "hypothesis": true}, {"text": "Частицы, которые сами заметно проводят ток, например глинистые, могут нарушать простую картину, где ток идёт только по воде.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Представьте передачу данных через сеть. Объём воды похож на число и ширину доступных каналов, солёность — на пропускную способность самой среды канала. Соединение пор похоже на топологию сети, а извилистость — на длину обходного маршрута по сравнению с прямым.", "breaks_where": "В сети эти параметры часто настраивают по отдельности, а в породе объём пор и их соединение задаёт строение самой породы. Ток не выбирает один маршрут, как пакет. Извилистость к тому же определена как квадрат отношения длин.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["Удельное сопротивление насыщенной осадочной породы, ом-метр", "Сведения о количестве флюида в порах", "Сведения о солёности флюида", "Сведения о соединении пор и извилистости"], "rule": "Если сопротивление двух интервалов различается, не приписывать различие одному фактору, пока не проверены остальные.", "conclusion": "Само по себе значение сопротивления не позволяет отделить влияние объёма флюида от влияния его солёности и соединения пор.", "counterexample": "Интервал с большим сопротивлением можно ошибочно счесть менее пористым, хотя причиной может быть менее солёная вода или иное соединение пор."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["насыщенная порода (saturated rock)", "солёность (salinity)", "извилистость (tortuosity)"], "links": [{"type": "prerequisite", "target": "keys.porosity_basics"}, {"type": "prerequisite", "target": "keys.resistivity_unit"}, {"type": "refutes_misconception", "target": "misc.high_res_oil"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Удельное электрическое сопротивление породы зависит от физических свойств самой породы и содержащихся в ней флюидов.", "kind": "observation", "page_pdf": 13, "unit_id": "p013.03", "quote": "The electrical resistivity of a rock depends on physical properties of the rock and the fluids it contains.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.rock_resistivity#c1"}, {"page_print": null, "text": "Большинство осадочных пород сложено частицами с очень высоким сопротивлением электрическому току.", "kind": "observation", "page_pdf": 13, "unit_id": "p013.03", "quote": "Most sedimentary rocks are composed of particles having a very high resistance to the flow of electrical current.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.rock_resistivity#c2"}, {"page_print": null, "text": "Когда такие осадочные породы насыщены, заполняющая поры вода проводит ток относительно хорошо по сравнению с частицами породы, или матрицей.", "kind": "observation", "page_pdf": 13, "unit_id": "p013.03", "quote": "When these rocks are saturated, the water filling the pore spaces is relatively conductive compared with the rock particles or matrix.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Речь о большинстве осадочных пород, частицы которых очень сильно сопротивляются току.", "quote": "Most sedimentary rocks are composed of particles having a very high resistance to the flow of electrical current."}], "id": "keys.rock_resistivity#c3"}, {"page_print": null, "text": "Поэтому сопротивление породы зависит от количества флюида, содержащегося в порах.", "kind": "inference", "page_pdf": 13, "unit_id": "p013.03", "quote": "The resistivity of a rock, therefore, is a function of the amount of fluid contained in the pore spaces, the salinity of that fluid, and how the pore spaces are interconnected.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Вывод опирается на то, что частицы большинства осадочных пород очень сильно сопротивляются току.", "quote": "Most sedimentary rocks are composed of particles having a very high resistance to the flow of electrical current."}], "id": "keys.rock_resistivity#c4"}, {"page_print": null, "text": "Сопротивление породы зависит от солёности флюида, содержащегося в порах.", "kind": "inference", "page_pdf": 13, "unit_id": "p013.03", "quote": "The resistivity of a rock, therefore, is a function of the amount of fluid contained in the pore spaces, the salinity of that fluid, and how the pore spaces are interconnected.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Вывод сделан после рассмотрения насыщенных пород, где поры заполнены водой.", "quote": "When these rocks are saturated, the water filling the pore spaces is relatively conductive"}], "id": "keys.rock_resistivity#c5"}, {"page_print": null, "text": "Сопротивление породы зависит от того, как поры соединены между собой.", "kind": "inference", "page_pdf": 13, "unit_id": "p013.03", "quote": "The resistivity of a rock, therefore, is a function of the amount of fluid contained in the pore spaces, the salinity of that fluid, and how the pore spaces are interconnected.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Вывод сделан после рассмотрения насыщенных пород, где поры заполнены водой.", "quote": "When these rocks are saturated, the water filling the pore spaces is relatively conductive"}], "id": "keys.rock_resistivity#c6"}, {"page_print": null, "text": "По мнению авторов, главным фактором геометрии пор, вероятно, является извилистость (tortuosity).", "kind": "inference", "page_pdf": 13, "unit_id": "p013.03", "quote": "The main factor in pore geometry is probably tortuosity, which is defined as the square of the ratio of the actual path length of the current", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.rock_resistivity#c7"}, {"page_print": null, "text": "Извилистость определяют как квадрат отношения действительной длины пути тока к длине образца, через который этот ток течёт.", "kind": "assumption", "page_pdf": 13, "unit_id": "p013.03", "quote": "tortuosity, which is defined as the square of the ratio of the actual path length of the current to the length of the sample through which it flows.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.rock_resistivity#c8"}, {"page_print": null, "text": "Удельное сопротивление измеряют в ом-метрах.", "kind": "assumption", "page_pdf": 13, "unit_id": "p013.03", "quote": "Resistivity is measured in ohm-meters, which is the resistance of a cube of material that is one meter on a side", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.rock_resistivity#c9"}, {"page_print": null, "text": "Для куба материала с ребром один метр сопротивление в омах численно равно удельному сопротивлению в ом-метрах.", "kind": "assumption", "page_pdf": 13, "unit_id": "p013.03", "quote": "the resistance of a cube of material that is one meter on a side, and the resistance of that cube, in ohms, is numerically equal to the resistivity, in ohm-meters.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.rock_resistivity#c10"}], "id": "keys.rock_resistivity", "order": 6, "minutes": 2, "essence": "Сопротивление насыщенной осадочной породы зависит от количества флюида в порах, его солёности и связности пор. Частицы большинства таких пород очень сильно сопротивляются току. Вода в порах проводит его сравнительно хорошо.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Осадочные породы образованы из осадков, и большинство из них сложено частицами с очень высоким сопротивлением току. Насыщенная порода (saturated rock) здесь означает породу, поры которой заполнены водой. Эта вода проводит ток относительно хорошо по сравнению с частицами, то есть с матрицей породы.", "pages": [13]}, {"text": "Отсюда автор выводит три фактора. Первый — сколько флюида содержится в порах. Второй — солёность (salinity) этого флюида, то есть содержание в нём растворённых солей.", "pages": [13]}, {"text": "Третий — то, как поры соединены между собой. Геометрию пор, то есть их форму и расположение, автор связывает прежде всего с извилистостью (tortuosity). Вероятно, это главный фактор такой геометрии.", "pages": [13]}, {"text": "Извилистость определяют так: длину действительного пути тока делят на длину образца и результат возводят в квадрат.", "pages": [13]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Удельное сопротивление измеряют в ом-метрах. Представьте куб материала с ребром один метр. Его сопротивление в омах численно равно удельному сопротивлению материала в ом-метрах.", "pages": [13]}, {"text": "Читая значение сопротивления, стоит помнить, что за ним стоят сразу несколько свойств породы и флюида.", "pages": [13]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Высокое сопротивление частиц автор приписывает большинству осадочных пород, а не всем породам. Проводимость воды названа высокой только относительно частиц, или матрицы. Главенство извилистости в геометрии пор автор подаёт с оговоркой «вероятно».", "pages": [13]}, {"text": "Извилистость — это квадрат отношения длин, а не само отношение. Числовых значений сопротивления или извилистости для конкретных пород здесь не приведено.", "pages": [13]}]}], "deeper": [{"text": "В общей формулировке автор говорит о физических свойствах и самой породы, и содержащихся в ней флюидов. Затем для насыщенных осадочных пород он выделяет объём флюида, его солёность и соединение пор.", "pages": [13]}], "glossary": [{"term": "насыщенная порода (saturated rock)", "definition": "Порода, поры которой заполнены флюидом; в объяснении проводимости здесь — водой."}, {"term": "солёность (salinity)", "definition": "Содержание растворённых солей во флюиде; одно из свойств, от которых зависит сопротивление породы."}, {"term": "извилистость (tortuosity)", "definition": "Квадрат отношения действительной длины пути тока к длине образца, через который он течёт."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [], "numbers": [], "formulas": [], "tables": [], "videos": [], "interactive": null, "narration": null}, {"title": "Общая пористость учитывает все поры, эффективная — только сообщающиеся", "short_title": "Общая и эффективная пористость", "why_here": {"text": "Уточняет определение пористости с учётом того, что ток идёт по связанным порам. Эффективная пористость понадобится для водоотдачи и формационного фактора.", "by_model": true}, "difficulty": {"primary": "П", "secondary": "И"}, "threshold": true, "pages": [15], "misconception": {"ref": null, "text": "«Пористость — всегда одна и та же величина, кто бы и чем её ни измерял». На деле различают общую и эффективную пористость. Каротажные методы и лабораторные методики могут давать разные результаты.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Значению пористости нужны два пояснения: общая она или эффективная и как получена. Электрический каротаж понижает показания сопротивления за счёт сообщающихся водонасыщенных пор, но не изолированных. Нейтронный каротаж не разделяет химически связанную и свободную воду. Лабораторные значения годятся для калибровки только после выяснения вида пористости и способа измерения.", "by_model": true}, "breaks": {"text": "Равенство общей и эффективной пористости нельзя переносить на вулканические и многие карбонатные породы, где часты изолированные пустоты. Сравнение значений ломается, если под словом «пористость» в источниках скрыты разные величины. Оно ломается и тогда, когда лабораторные значения получены разными методиками.", "by_model": true}, "hypotheses": [{"text": "В таблице с данными полезно хранить рядом с пористостью столбцы «вид пористости», «метод измерения» и «источник».", "by_model": true, "hypothesis": true}, {"text": "Расхождение оценок пористости по нейтронному и электрическому каротажу может указывать на связанную воду или изолированные поры. Другие причины тоже нужно проверить.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Общая пористость похожа на все диски в серверной, а эффективная — только на диски, подключённые к сети. Отключённый диск занимает место, но данные через него не передаются.", "breaks_where": "Диск можно подключить, а изолированная пора в этой аналогии не переключается по команде. Связность пор ещё не говорит, насколько легко течёт флюид. Для воды в глинистых минералах и кристаллах аналогия тоже ничего не объясняет.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Лабораторные значения пористости на образцах, сведения о методике измерения и отклик каротажа.", "manual_steps": "Выяснить, какую пористость измерили на образцах и каким способом, и лишь затем использовать значения для калибровки.", "judgment_points": "Решить, общая или эффективная пористость имеется в виду. Оценить, возможны ли изолированные пустоты или связанная вода.", "time": "в главе не указано", "typical_errors": "Принять эффективную пористость из литературы за общую. Калибровать каротаж по значениям неизвестного вида или метода. Считать воду в кристаллах гипса частью общей пористости.", "by_model": true}, "decision_on_data": {"features": ["Вид пористости, измеренной на образцах: общая или эффективная", "Лабораторная методика измерения", "Тип породы: обломочная, вулканическая или карбонатная", "Метод каротажа, отклик которого калибруют"], "rule": "Пока неизвестны вид пористости и способ измерения, лабораторные значения не используют для калибровки отклика каротажа.", "conclusion": "Калибровку начинают после выяснения этих сведений. В вулканических и многих карбонатных породах особенно важно не смешивать общую и эффективную пористость.", "counterexample": "В большинстве обломочных осадочных пород общая и эффективная пористость почти совпадают, и их смешение там может мало сказаться. Но разные лабораторные методики всё равно могут давать разные результаты."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["общая пористость (total porosity)", "эффективная пористость (effective porosity)", "обломочные породы (detrital rocks)", "карбонатные породы (carbonate rocks)"], "links": [{"type": "prerequisite", "target": "keys.porosity_basics"}, {"type": "prerequisite", "target": "keys.rock_resistivity"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Общая пористость (total porosity) включает все поровые пространства в материале, независимо от того, сообщаются они между собой или нет.", "kind": "assumption", "page_pdf": 15, "unit_id": "p015.04", "quote": "includes all the pore spaces in a material, regardless of whether they are interconnected or not.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c1"}, {"page_print": null, "text": "В этом руководстве общую пористость называют просто пористостью.", "kind": "assumption", "page_pdf": 15, "unit_id": "p015.04", "quote": "Total porosity, which will be called simply porosity in this manual", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c2"}, {"page_print": null, "text": "Эффективная пористость (effective porosity) охватывает только взаимосвязанные поры, которые поэтому эффективны в передаче флюидов.", "kind": "assumption", "page_pdf": 15, "unit_id": "p015.04", "quote": "Effective porosity encompasses only the pore spaces that are interconnected and, therefore, effective in transmitting fluids.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c3"}, {"page_print": null, "text": "В большинстве обломочных (detrital) осадочных пород эффективная и общая пористость почти одинаковы.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "In most detrital sedimentary rocks, effective and total porosity are nearly the same;", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c4"}, {"page_print": null, "text": "В вулканических и во многих карбонатных породах (carbonate rocks), напротив, часто встречаются изолированные пустоты.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "however, in volcanic rocks and in many carbonate rocks, isolated voids are common.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c5"}, {"page_print": null, "text": "Заполненные водой несообщающиеся поры не понижают удельное сопротивление, измеряемое электрическим каротажем, а сообщающиеся понижают.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "Unconnected pore spaces filled with water do not lower the resistivity measured by an electric log, whereas connected spaces do.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c6"}, {"page_print": null, "text": "При определении пористости по каротажу нужно учитывать дополнительный фактор: воду, удерживаемую между слоями в глинистых минералах.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "An additional factor to consider in interpreting porosity from logs is introduced by water held between layers in the clay minerals.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c7"}, {"page_print": null, "text": "На нейтронном каротаже химически связанную воду нельзя отличить от свободной.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "Chemically bound water cannot be distinguished from free water on a neutron log.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c8"}, {"page_print": null, "text": "В некоторой литературе по каротажу термин «пористость» (porosity) означает эффективную пористость.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "In some logging literature, the term \"porosity\" is used for effective porosity", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c9"}, {"page_print": null, "text": "В некоторой литературе по каротажу вводят коэффициенты «глинистости» (shaliness) для исправления методов, откликающихся на несообщающиеся пустоты или химически связанную воду.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "and \"shaliness\" factors are introduced for correction of logs that respond to unconnected voids or chemically bound water.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c10"}, {"page_print": null, "text": "Воду в кристаллической структуре минералов, таких как гипс, не следует считать частью общей пористости.", "kind": "assumption", "page_pdf": 15, "unit_id": "p015.04", "quote": "Water in the crystal structure of minerals, such as gypsum, should not be considered to be part of the total porosity.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c11"}, {"page_print": null, "text": "Истолкование пористости по геофизическому каротажу дополнительно осложняется тем, что есть несколько лабораторных методик её измерения, и все они могут давать разные результаты (Jenkins, 1966).", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "there are several different laboratory techniques for measuring porosity, all of which may give different results (Jenkins, R. J., 1966).", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c12"}, {"page_print": null, "text": "Прежде чем калибровать отклик каротажа по лабораторным значениям, необходимо определить, какой вид пористости измерен на образцах и как это сделано.", "kind": "inference", "page_pdf": 15, "unit_id": "p015.04", "quote": "before any attempt is made to use laboratory values for calibrating log response, one must determine the kind of porosity that was measured on the samples and how it was done.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.total_effective_porosity#c13"}], "id": "keys.total_effective_porosity", "order": 7, "minutes": 3, "essence": "Общая пористость учитывает все поры, а эффективная — только сообщающиеся между собой. В большинстве обломочных пород они почти одинаковы. В вулканических и многих карбонатных породах часто есть изолированные пустоты.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Общая пористость включает любые поровые пространства, соединены они друг с другом или нет. В этом руководстве авторы называют её просто пористостью. Эффективная пористость охватывает только взаимосвязанные поры, которые поэтому участвуют в передаче флюидов.", "pages": [15]}, {"text": "Обломочные породы (detrital rocks) — это осадочные породы, сложенные обломками других пород и минералов. В большинстве из них эффективная и общая пористость почти совпадают. Иначе бывает в вулканических породах и во многих карбонатных породах (carbonate rocks), например известняках и доломитах.", "pages": [15]}, {"text": "Там часто встречаются изолированные пустоты. Связность видна и на электрическом каротаже. Заполненные водой сообщающиеся поры понижают измеряемое удельное сопротивление, а несообщающиеся — нет.", "pages": [15]}, {"text": "Ещё одно осложнение — вода, удерживаемая между слоями в глинистых минералах. Нейтронный каротаж не отличает химически связанную воду от свободной. При этом воду в кристаллической структуре минералов, например гипса, не следует считать частью общей пористости.", "pages": [15]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Встретив слово «пористость», стоит проверить, какая именно величина имеется в виду. В части каротажной литературы так называют эффективную пористость. Там же вводят коэффициенты «глинистости» (shaliness).", "pages": [15]}, {"text": "Это поправки для методов, которые откликаются на несообщающиеся пустоты или химически связанную воду. Лабораторные значения часто нужны для калибровки, то есть привязки отклика прибора к измерениям на образцах. До этого следует выяснить, какую пористость измерили на образцах и каким способом.", "pages": [15]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Близость общей и эффективной пористости заявлена для большинства обломочных осадочных пород, а не для всех. Изолированные пустоты названы частыми в вулканических и многих карбонатных породах. Насколько именно расходятся две величины, автор в этом фрагменте не указывает.", "pages": [15]}, {"text": "Лабораторных методик измерения пористости несколько, и все они могут давать разные результаты. Автор ссылается здесь на работу Jenkins (1966).", "pages": [15]}]}], "deeper": [{"text": "Трудность возникает на двух уровнях. Приборы по-разному реагируют на изолированные поры и связанную воду. Лабораторные методы, с которыми сравнивают каротаж, тоже могут расходиться между собой. Поэтому расхождение двух оценок пористости само по себе ещё не означает ошибку измерения.", "pages": [15]}], "glossary": [{"term": "общая пористость (total porosity)", "definition": "Пористость, учитывающая все поровые пространства в материале, сообщающиеся и несообщающиеся."}, {"term": "эффективная пористость (effective porosity)", "definition": "Пористость, учитывающая только сообщающиеся поры, которые участвуют в передаче флюидов."}, {"term": "обломочные породы (detrital rocks)", "definition": "Осадочные породы, сложенные обломками других пород и минералов."}, {"term": "карбонатные породы (carbonate rocks)", "definition": "Породы, сложенные в основном карбонатными минералами, например известняки и доломиты."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [{"text": "Проверьте, не называет ли используемая литература по каротажу «пористостью» эффективную пористость.", "pages": [15], "claim_id": "keys.total_effective_porosity#c9"}, {"text": "Определите, какой вид пористости измерен на лабораторных образцах.", "pages": [15], "claim_id": "keys.total_effective_porosity#c13"}, {"text": "Выясните, каким способом измеряли эту пористость, поскольку разные методики могут давать разные результаты.", "pages": [15], "claim_id": "keys.total_effective_porosity#c12"}, {"text": "Только после этого используйте лабораторные значения для калибровки отклика каротажа.", "pages": [15], "claim_id": "keys.total_effective_porosity#c13"}], "numbers": [{"text": "Истолкование пористости по геофизическому каротажу дополнительно осложняется тем, что есть несколько лабораторных методик её измерения, и все они могут давать разные результаты (Jenkins, 1966).", "page": 15, "claim_id": "keys.total_effective_porosity#c12"}], "formulas": [], "tables": [], "videos": [], "interactive": null, "narration": null}, {"title": "Связанная вода и разные лабораторные методы искажают сравнение значений пористости", "short_title": "Почему значения пористости трудно сравнивать", "why_here": {"text": "Опирается на различие общей и эффективной пористости. Предупреждает, что перед калибровкой каротажа по керну надо знать, что именно измерено.", "by_model": true}, "difficulty": {"primary": "Н", "secondary": "И"}, "threshold": false, "pages": [15], "misconception": {"ref": null, "text": "«Пористость — одно однозначное число, поэтому лабораторию и каротаж можно сравнивать напрямую». На деле сначала нужно узнать вид пористости и способ измерения. Разные лабораторные методы могут давать разные результаты, а приборы по-разному реагируют на изолированные поры и связанную воду.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Для калибровки у лабораторного значения пористости должны быть известны вид измеренной пористости и способ измерения. Электрический каротаж и нейтронный каротаж нельзя считать откликами на один и тот же набор воды. Несообщающиеся водонасыщенные поры не понижают измеряемое сопротивление. Нейтронный каротаж не отличает химически связанную воду от свободной.", "by_model": true}, "breaks": {"text": "Сравнение ломается, если неизвестно, общую или эффективную пористость измерили, или каким методом. Оно усложняется в вулканических и многих карбонатных породах с изолированными пустотами. Оно усложняется и там, где есть вода в глинистых минералах или химически связанная вода.", "by_model": true}, "hypotheses": [{"text": "В таблице калибровки полезно хранить рядом с каждым значением пористости столбцы «вид пористости», «лабораторный метод» и «литология».", "by_model": true, "hypothesis": true}, {"text": "Значения, полученные разными лабораторными методами, разумно сначала сравнивать по отдельности, а не объединять в одну выборку.", "by_model": true, "hypothesis": true}, {"text": "Систематическое расхождение нейтронного каротажа с эффективной пористостью в глинистых интервалах может указывать на вклад связанной воды.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это как сводить метрику «число пользователей» из разных систем. Одна считает все учётные записи, другая — только активные, и способы подсчёта различаются. До сравнения нужно прочитать определение метрики и узнать, как её собрали.", "breaks_where": "В ИТ часто можно пересчитать метрику из сырых записей по единому определению. С породой прибор даёт косвенный отклик, и нейтронный каротаж сам не разделяет связанную и свободную воду.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Лабораторные значения пористости образцов, сведения о виде пористости и методе измерения, каротажные диаграммы.", "manual_steps": "Выяснить для лабораторных значений, какая пористость измерена и каким способом. Проверить, что называют «пористостью» в используемой литературе. Только после этого калибровать каротаж.", "judgment_points": "Можно ли сопоставлять данное лабораторное значение с откликом конкретного метода. Нужна ли поправка на глинистость. Есть ли в породе изолированные пустоты или связанная вода.", "time": "в главе не указано", "typical_errors": "Принять эффективную пористость за общую. Объединить результаты разных лабораторных методов без проверки. Считать воду в кристаллической структуре минералов частью общей пористости.", "by_model": true}, "decision_on_data": {"features": ["Известен ли вид пористости, измеренной на образцах", "Известен ли лабораторный метод измерения", "Тип породы: обломочная осадочная, вулканическая или карбонатная", "Есть ли глинистые минералы или химически связанная вода", "Какой каротаж калибруют"], "rule": "Если неизвестно, какую пористость измерили или как, лабораторные значения пока не использовать для калибровки. Сначала выяснить оба пункта.", "conclusion": "Когда вид и метод известны, можно оценивать, соответствует ли лабораторная величина тому, на что реагирует каротаж.", "counterexample": "Вид и метод известны, но нейтронный каротаж всё равно не отличает химически связанную воду от свободной. Поэтому одних этих сведений может быть недостаточно для совпадения значений."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["глинистые минералы (clay minerals)", "химически связанная вода (chemically bound water)", "поправка на глинистость (shaliness factor)", "калибровка каротажа (calibrating log response)"], "links": [{"type": "prerequisite", "target": "keys.porosity_basics"}, {"type": "prerequisite", "target": "keys.total_effective_porosity"}, {"type": "prerequisite", "target": "keys.rock_resistivity"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Общая пористость, которую в этом руководстве называют просто пористостью, включает все поровые пространства материала независимо от того, сообщаются они или нет.", "kind": "assumption", "page_pdf": 15, "unit_id": "p015.04", "quote": "Total porosity, which will be called simply porosity in this manual, includes all the pore spaces in a material, regardless of whether they are interconnected or not.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_measurement_pitfalls#c1"}, {"page_print": null, "text": "Эффективная пористость охватывает только сообщающиеся поровые пространства, которые поэтому эффективны для передачи флюидов.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "Effective porosity encompasses only the pore spaces that are interconnected and, therefore, effective in transmitting fluids.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_measurement_pitfalls#c2"}, {"page_print": null, "text": "В большинстве обломочных осадочных пород эффективная и общая пористость почти одинаковы.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "In most detrital sedimentary rocks, effective and total porosity are nearly the same;", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_measurement_pitfalls#c3"}, {"page_print": null, "text": "В вулканических породах и во многих карбонатных породах, напротив, часто встречаются изолированные пустоты.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "however, in volcanic rocks and in many carbonate rocks, isolated voids are common.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_measurement_pitfalls#c4"}, {"page_print": null, "text": "Несообщающиеся поры, заполненные водой, не понижают удельное сопротивление, измеряемое электрическим каротажем, а сообщающиеся понижают.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "Unconnected pore spaces filled with water do not lower the resistivity measured by an electric log, whereas connected spaces do.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_measurement_pitfalls#c5"}, {"page_print": null, "text": "При интерпретации пористости по каротажу нужно учитывать дополнительный фактор: воду, удерживаемую между слоями в глинистых минералах (clay minerals).", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "An additional factor to consider in interpreting porosity from logs is introduced by water held between layers in the clay minerals.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_measurement_pitfalls#c6"}, {"page_print": null, "text": "На диаграмме нейтронного каротажа химически связанную воду (chemically bound water) нельзя отличить от свободной.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "Chemically bound water cannot be distinguished from free water on a neutron log.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_measurement_pitfalls#c7"}, {"page_print": null, "text": "В некоторых работах по каротажу термин «пористость» используют для эффективной пористости.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "In some logging literature, the term \"porosity\" is used for effective porosity,", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_measurement_pitfalls#c8"}, {"page_print": null, "text": "В некоторых работах по каротажу вводят поправки на глинистость (shaliness factors) для методов, реагирующих на несообщающиеся пустоты или химически связанную воду.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "and \"shaliness\" factors are introduced for correction of logs that respond to unconnected voids or chemically bound water.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_measurement_pitfalls#c9"}, {"page_print": null, "text": "Воду в кристаллической структуре минералов, таких как гипс (gypsum), не следует считать частью общей пористости.", "kind": "assumption", "page_pdf": 15, "unit_id": "p015.04", "quote": "Water in the crystal structure of minerals, such as gypsum, should not be considered to be part of the total porosity.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_measurement_pitfalls#c10"}, {"page_print": null, "text": "Интерпретацию пористости по геофизическому каротажу дополнительно усложняет то, что есть несколько разных лабораторных методов её измерения, и все они могут давать разные результаты (Jenkins, R. J., 1966).", "kind": "observation", "page_pdf": 15, "unit_id": "p015.04", "quote": "To further complicate the interpretation of porosity from geophysical logs, there are several different laboratory techniques for measuring porosity, all of which may give different results (Jenkins, R. J., 1966).", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_measurement_pitfalls#c11"}, {"page_print": null, "text": "Поэтому до любой попытки калибровать отклик каротажа по лабораторным значениям нужно определить, какой вид пористости измерен на образцах и как это сделано.", "kind": "inference", "page_pdf": 15, "unit_id": "p015.04", "quote": "Therefore, before any attempt is made to use laboratory values for calibrating log response, one must determine the kind of porosity that was measured on the samples and how it was done.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.porosity_measurement_pitfalls#c12"}], "id": "keys.porosity_measurement_pitfalls", "order": 8, "minutes": 3, "essence": "Перед калибровкой каротажа по лабораторным значениям нужно узнать, какую пористость измерили и как. Разные лабораторные методы могут давать разные результаты. Изолированные поры и связанная вода тоже усложняют интерпретацию.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Общая пористость учитывает все поры, эффективная — только сообщающиеся. В большинстве обломочных осадочных пород они почти совпадают. В вулканических и многих карбонатных породах часто встречаются изолированные пустоты.", "pages": [15]}, {"text": "Приборы по-разному «замечают» воду. Электрический каротаж измеряет удельное электрическое сопротивление (resistivity). Заполненные водой несообщающиеся поры его не понижают, а сообщающиеся понижают.", "pages": [15]}, {"text": "Ещё один фактор — глинистые минералы (clay minerals), то есть минералы, слагающие глины. Между их слоями удерживается вода. Химически связанная вода (chemically bound water) — это вода, удерживаемая веществом породы химическими связями.", "pages": [15]}, {"text": "Нейтронный каротаж не может отличить её от свободной воды.", "pages": [15]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Калибровка каротажа (calibrating log response) — это сопоставление отклика прибора с известными значениями свойства. Здесь такими значениями служат лабораторные измерения на образцах. До любой попытки такой калибровки нужно выяснить две вещи.", "pages": [15]}, {"text": "Первая: какой вид пористости измерен на образцах. Вторая: как именно его измеряли. Читая литературу по каротажу, стоит проверять смысл слова «пористость».", "pages": [15]}, {"text": "В некоторых работах так называют эффективную пористость. Там же вводят поправку на глинистость (shaliness factor). Она исправляет показания методов, реагирующих на несообщающиеся пустоты или химически связанную воду.", "pages": [15]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Близость общей и эффективной пористости указана для большинства обломочных осадочных пород, а не для всех. Изолированные пустоты часты во многих карбонатных породах, но не обязательно во всех. Гипс (gypsum) — минерал, в кристаллической структуре которого есть вода.", "pages": [15]}, {"text": "Такую воду в минералах не следует считать частью общей пористости. Про лабораторные методы сказано, что все они могут давать разные результаты. Это не значит, что результаты всегда расходятся.", "pages": [15]}, {"text": "Автор ссылается здесь на работу Jenkins, R. J., 1966. Величину расхождений он в этом месте не называет.", "pages": [15]}]}], "deeper": [{"text": "В этом руководстве общую пористость называют просто пористостью. В части каротажной литературы тем же словом обозначают эффективную. Поэтому два одинаково подписанных числа могут относиться к разным величинам.", "pages": [15]}], "glossary": [{"term": "глинистые минералы (clay minerals)", "definition": "Минералы, слагающие глины; между их слоями может удерживаться вода, что нужно учитывать при определении пористости по каротажу."}, {"term": "химически связанная вода (chemically bound water)", "definition": "Вода, удерживаемая веществом породы химическими связями; нейтронный каротаж не отличает её от свободной воды."}, {"term": "поправка на глинистость (shaliness factor)", "definition": "Поправка для каротажных методов, реагирующих на несообщающиеся пустоты или химически связанную воду."}, {"term": "калибровка каротажа (calibrating log response)", "definition": "Сопоставление отклика каротажного прибора с известными значениями свойства, например с лабораторными измерениями пористости на образцах."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [{"text": "Определите, какой вид пористости измерен на образцах: общая или эффективная.", "pages": [15], "claim_id": "keys.porosity_measurement_pitfalls#c12"}, {"text": "Выясните, каким лабораторным методом получены значения, так как разные методы могут давать разные результаты.", "pages": [15], "claim_id": "keys.porosity_measurement_pitfalls#c11"}, {"text": "Только после этого калибруйте отклик каротажа по лабораторным значениям.", "pages": [15], "claim_id": "keys.porosity_measurement_pitfalls#c12"}], "numbers": [{"text": "Интерпретацию пористости по геофизическому каротажу дополнительно усложняет то, что есть несколько разных лабораторных методов её измерения, и все они могут давать разные результаты (Jenkins, R. J., 1966).", "page": 15, "claim_id": "keys.porosity_measurement_pitfalls#c11"}], "formulas": [], "tables": [], "videos": [], "interactive": null, "narration": null}, {"title": "Первичная пористость возникает при осадконакоплении, вторичная — позже и распределена неравномерно", "short_title": "Первичные и вторичные пустоты в породе", "why_here": {"text": "Добавляет к видам пористости их происхождение. Объясняет, почему некоторые методы ошибаются в неоднородных породах.", "by_model": true}, "difficulty": {"primary": "В", "secondary": "П"}, "threshold": false, "pages": [15], "misconception": {"ref": null, "text": "Поры в породе остаются такими, какими были при отложении осадка. На деле уплотнение и цементация уменьшают первичную пористость. Растворение, трещины и химические преобразования создают вторичную уже после отложения.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Значение пористости по акустическому каротажу или некоторым видам каротажа сопротивления может быть ошибочным при неоднородно распределённых пустотах. Нейтронный зонд обычно даёт усреднение по заполненным водой порам в исследуемом объёме. Литологические признаки по некоторым диаграммам обычно связаны с первичной пористостью.", "by_model": true}, "breaks": {"text": "Связь пористости с литологией может не работать для вторичных полостей растворения в известняке. Они могут располагаться несмотря на литологические различия. Тогда определить их положение по литологии нельзя, нужно прямое обнаружение.", "by_model": true}, "hypotheses": [{"text": "Расхождение пористости по нейтронному и акустическому каротажу в одном интервале может быть поводом проверить наличие вторичной пористости. Расхождение может иметь и другие причины.", "by_model": true, "hypothesis": true}, {"text": "В таблице данных полезно хранить пористость по каждому методу отдельным столбцом, не заменяя их одним «общим» значением.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Первичная пористость похожа на исходную разметку хранилища при развёртывании: она довольно равномерна и следует из начальной конфигурации. Вторичная похожа на последующие локальные изменения, которые ложатся неравномерно. По исходной конфигурации их расположение не всегда можно предсказать.", "breaks_where": "Изменения в ИТ обычно кем-то задуманы и записаны в журнале. Растворение и трещины никто не планирует и не протоколирует. Кроме того, первичные поры сами сокращаются при уплотнении и цементации.", "by_model": true}, "now_practice": {"text": "Трещины и подобные пустоты сегодня изучают электрическими и акустическими имиджерами стенки скважины, а также по керну. Нейтронный каротаж обычно ведут двухзондовым компенсированным прибором, калиброванным в единицах пористости.", "by_model": true}, "inefficiency_lens": {"inputs": "Каротажные диаграммы: акустические, сопротивления, нейтронные; сведения о литологии породы.", "manual_steps": "Истолковывает литологию по диаграммам и ищет вторичные полости прямым обнаружением.", "judgment_points": "Оценивает, насколько неравномерны пустоты и можно ли доверять пористости по конкретному виду каротажа.", "time": "в главе не указано", "typical_errors": "Ошибочная пористость по акустическому каротажу и некоторым видам каротажа сопротивления при неоднородных пустотах.", "by_model": true}, "decision_on_data": {"features": ["Есть основания считать, что пустоты распределены неоднородно (например, полости растворения или трещины).", "Пористость получена акустическим каротажом или некоторыми видами каротажа сопротивления."], "rule": "Если пустоты распределены неоднородно, значение пористости по этим методам следует считать возможно ошибочным.", "conclusion": "Не принимать такое значение без проверки. Для определения положения вторичных полостей растворения нужно прямое обнаружение.", "counterexample": "Неоднородность не означает, что значение обязательно неверно: автор пишет лишь, что ошибка возможна. И не все виды каротажа сопротивления подвержены ей."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["первичная пористость (primary porosity)", "вторичная пористость (secondary porosity)", "уплотнение (compaction)", "цементация (cementation)", "доломитизация (dolomitization)"], "links": [{"type": "prerequisite", "target": "keys.porosity_basics"}, {"type": "prerequisite", "target": "keys.total_effective_porosity"}, {"type": "prerequisite", "target": "keys.log_and_rock"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Пористость также делят на первичную (primary porosity), то есть межзерновое поровое пространство, и вторичную (secondary porosity).", "kind": "assumption", "page_pdf": 15, "unit_id": "p015.05", "quote": "Porosity is also divided into primary porosity, or intergranular pore space, and secondary porosity.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c1"}, {"page_print": null, "text": "Первичная пористость характерна для обломочных пород.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "Primary porosity is characteristic of detrital rocks, related to the original size and shape of the grains", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c2"}, {"page_print": null, "text": "Первичная пористость обломочных пород связана с исходными размером и формой зёрен.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "Primary porosity is characteristic of detrital rocks, related to the original size and shape of the grains", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c3"}, {"page_print": null, "text": "Первичную пористость уменьшают уплотнение (compaction) и цементация (cementation).", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "related to the original size and shape of the grains and reduced by compaction and cementation.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c4"}, {"page_print": null, "text": "Первичная пористость обычно распределена однородно.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "Primary porosity tends to be homogeneously distributed.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c5"}, {"page_print": null, "text": "Вторичные поровые пространства образуются после того, как порода отложилась.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "Secondary pore spaces, which are formed after the rock is deposited, tend to be nonhomogeneous.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c6"}, {"page_print": null, "text": "Вторичные поровые пространства, образовавшиеся после отложения породы, обычно неоднородны.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "Secondary pore spaces, which are formed after the rock is deposited, tend to be nonhomogeneous.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c7"}, {"page_print": null, "text": "Одна из причин вторичной пористости — химическое растворение.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "Secondary porosity is caused by chemical solution, by fracturing and jointing", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c8"}, {"page_print": null, "text": "Вторичную пористость вызывают также растрескивание и образование отдельности (fracturing and jointing).", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "Secondary porosity is caused by chemical solution, by fracturing and jointing", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c9"}, {"page_print": null, "text": "Вторичную пористость вызывает и химическое преобразование, например доломитизация (dolomitization) и переход ангидрита в гипс.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "and by chemical alteration, such as dolomitization, and the alteration of anhydrite to gypsum.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c10"}, {"page_print": null, "text": "Там, где пустоты распределены неоднородно, акустический каротаж и некоторые виды каротажа сопротивления могут давать ошибочные значения пористости.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "The acoustic-velocity log and some resistivity logs can provide erroneous porosities where the voids are nonhomogeneously distributed.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c11"}, {"page_print": null, "text": "Нейтронный зонд (neutron probe) обычно усредняет заполненные водой поровые пространства в пределах исследуемого объёма.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "The neutron probe tends to average the water-filled pore spaces within the volume investigated.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c12"}, {"page_print": null, "text": "Первичная пористость обычно связана с литологическим характером осадка.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "Primary porosity is generally related to a lithologic character of the sediment", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c13"}, {"page_print": null, "text": "Литологический характер осадка, с которым обычно связана первичная пористость, можно интерпретировать по некоторым геофизическим каротажным диаграммам.", "kind": "inference", "page_pdf": 15, "unit_id": "p015.05", "quote": "related to a lithologic character of the sediment, which may be interpreted from certain geophysical logs.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c14"}, {"page_print": null, "text": "В отличие от первичной пористости, вторичные полости растворения могут быть распределены в известняке несмотря на его литологические различия.", "kind": "observation", "page_pdf": 15, "unit_id": "p015.05", "quote": "In contrast, secondary solution openings may be distributed within a limestone, despite its lithologic differences.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c15"}, {"page_print": null, "text": "Чтобы определить положение таких вторичных полостей растворения внутри породы, нужно полагаться на прямое обнаружение.", "kind": "inference", "page_pdf": 15, "unit_id": "p015.05", "quote": "To locate these voids within the rock, one must rely on direct detection.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.primary_secondary_porosity#c16"}], "id": "keys.primary_secondary_porosity", "order": 9, "minutes": 3, "essence": "Первичные поры возникают при осадконакоплении, а вторичные пустоты образуются уже после отложения породы. Первичные обычно распределены однородно, вторичные, как правило, неравномерно. Из-за этой неравномерности некоторые виды каротажа могут давать ошибочную пористость.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Первичная пористость характерна для обломочных пород. Она связана с исходными размером и формой зёрен. Уменьшают её два процесса.", "pages": [15]}, {"text": "Уплотнение (compaction) — это сжатие осадка, при котором зёрна располагаются теснее. Цементация (cementation) — это отложение минерального вещества, скрепляющего зёрна и занимающего часть пор. Вторичные пустоты образуются уже после отложения породы.", "pages": [15]}, {"text": "Автор называет несколько причин. Первая — химическое растворение. Вторая — растрескивание и образование отдельности (jointing), то есть системы трещин в породе.", "pages": [15]}, {"text": "Третья — химическое преобразование породы. Его примеры: доломитизация (dolomitization) и переход ангидрита (anhydrite) в гипс (gypsum). Доломитизация — это превращение известковой породы в доломит.", "pages": [15]}, {"text": "Ангидрит и гипс — сульфаты кальция, без воды и с водой в кристаллах.", "pages": [15]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Акустический каротаж и некоторые виды каротажа сопротивления могут ошибаться в пористости при неоднородно распределённых пустотах. Нейтронный зонд (neutron probe) обычно усредняет заполненные водой поры в исследуемом им объёме. Первичная пористость обычно связана с литологическим характером осадка.", "pages": [15]}, {"text": "Этот характер можно истолковать по некоторым каротажным диаграммам. Вторичные полости растворения в известняке (limestone) могут располагаться несмотря на его литологические различия. Чтобы найти такие пустоты, приходится полагаться на прямое обнаружение.", "pages": [15]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Однородность первичных пор и неоднородность вторичных автор описывает как склонность, а не как строгое правило. Ошибочные значения возможны, но не обязательны. Речь идёт не обо всех видах каротажа сопротивления, а о некоторых.", "pages": [15]}, {"text": "Автор не уточняет здесь, о каких именно. Усреднение нейтронным зондом относится к порам, заполненным водой, и к исследуемому объёму. Из этого не следует, что зонд показывает положение отдельных пустот.", "pages": [15]}, {"text": "Какими средствами вести прямое обнаружение, в этом месте не названо.", "pages": [15]}]}], "deeper": [{"text": "Первичную пористость автор прямо приравнивает к межзерновому поровому пространству. Деление по происхождению отличается от деления на общую и эффективную пористость. Там признаком служит сообщаемость пор, а здесь — время и способ их образования.", "pages": [15]}], "glossary": [{"term": "первичная пористость (primary porosity)", "definition": "Межзерновое поровое пространство, характерное для обломочных пород. Связана с исходными размером и формой зёрен."}, {"term": "вторичная пористость (secondary porosity)", "definition": "Пустоты, образовавшиеся после отложения породы: от растворения, трещин или химического преобразования."}, {"term": "уплотнение (compaction)", "definition": "Сжатие осадка, при котором зёрна располагаются теснее, а первичная пористость уменьшается."}, {"term": "цементация (cementation)", "definition": "Отложение минерального вещества, скрепляющего зёрна; оно уменьшает первичную пористость."}, {"term": "доломитизация (dolomitization)", "definition": "Химическое преобразование известковой породы в доломит; одна из причин вторичной пористости."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [], "numbers": [], "formulas": [], "tables": [], "videos": [], "interactive": null, "narration": null}, {"title": "Водоотдача показывает, сколько воды порода отдаст под действием силы тяжести", "short_title": "Сколько воды отдаст порода", "why_here": {"text": "Опирается на эффективную пористость: часть воды стекает, часть удерживается. Позже связывается с размером зёрен.", "by_model": true}, "difficulty": {"primary": "М", "secondary": "И"}, "threshold": false, "pages": [15, 16], "misconception": {"ref": null, "text": "Кажется, что порода отдаст всю воду из сообщающихся пор. На деле под действием силы тяжести стекает только часть, соответствующая водоотдаче. Остальное относится к водоудерживающей способности.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Искомая величина — водоотдача: объём воды, отданной под действием силы тяжести, делённый на объём породы. Её можно оценить по геофизическому каротажу. Для безнапорного пласта описано применение нейтронного зонда, а в табл. 1 названы калиброванные нейтронные диаграммы. Водоотдача связана с распределением зёрен по размерам и с пористостью.", "by_model": false}, "breaks": {"text": "Сравнивать материалы по водоотдаче следует после завершения гравитационного дренирования. Ряд «средний песок — алевриты и глины» дан только как общий случай. Нейтронная диаграмма не отличает химически связанную воду от свободной.", "by_model": true}, "hypotheses": [{"text": "Повторные нейтронные замеры до и после понижения уровня воды могли бы показать, сколько воды стекло из породы.", "by_model": true, "hypothesis": true}, {"text": "Если дренирование ещё не закончилось, оценка по разности замеров, вероятно, окажется заниженной.", "by_model": true, "hypothesis": true}, {"text": "В таблице данных полезно хранить тип породы, сведения о размерах зёрен, пористость и время дренирования рядом с оценкой водоотдачи.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Представьте пул ресурсов после остановки нагрузки: часть ресурсов освобождается сама, часть остаётся удержанной. Освободившаяся часть похожа на водоотдачу, удержанная — на водоудерживающую способность. Вместе они дают всё, что находилось в доступной части пула.", "breaks_where": "В ИТ удержание обычно задано кодом или настройками. В породе водоотдача связана с размерами зёрен и пористостью. Кроме того, водоотдачу относят к объёму всей породы, а не только доступной ёмкости.", "by_model": true}, "now_practice": {"text": "Нейтронный каротаж обычно ведут двухзондовым компенсированным прибором. Связанную и подвижную воду также оценивают импульсным ЯМР-каротажем.", "by_model": true}, "inefficiency_lens": {"inputs": "Геофизические каротажные диаграммы, показания нейтронного зонда, распределение зёрен по размерам и пористость.", "manual_steps": "Оценивает водоотдачу по каротажу и сравнивает способность разных материалов отдавать воду.", "judgment_points": "Решает, завершилось ли гравитационное дренирование и можно ли сравнивать материалы.", "time": "в главе не указано", "typical_errors": "в главе не указано", "by_model": true}, "decision_on_data": {"features": ["Тип материала: среднезернистый песок, алеврит или глина", "Распределение зёрен по размерам", "Пористость"], "rule": "В общем случае у среднезернистого песка водоотдача наибольшая, а у алевритов и глин — наименьшая.", "conclusion": "При прочих неизвестных от среднезернистого песка можно ожидать большей отдачи воды, чем от алеврита или глины. Это предварительное ожидание, а не измеренное значение.", "counterexample": "Возможный случай (предположение модели): песок со средним размером зёрен, но с очень разными по размеру зёрнами. Автор связывает высокую водоотдачу с однородностью, поэтому одного названия «средний песок» может не хватить."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["водоотдача (specific yield)", "водоудерживающая способность (specific retention)", "гравитационное дренирование (gravity drainage)", "безнапорный водоносный пласт (unconfined aquifer)", "коэффициент упругоёмкости (storage coefficient)"], "links": [{"type": "prerequisite", "target": "keys.porosity_basics"}, {"type": "prerequisite", "target": "keys.total_effective_porosity"}], "needs_scan": [], "claims": [{"page_print": null, "text": "По мнению автора, водоотдача (specific yield) очень важна при изучении подземных вод. Когда гравитационное дренирование (gravity drainage) завершено, она позволяет сравнивать способность разных материалов отдавать воду.", "kind": "inference", "page_pdf": 15, "unit_id": "p015.07", "quote": "Specific yield is very important in ground-water studies because, when gravity drainage is complete, it is a means of comparing the various capacities of different materials to yield water.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.specific_yield#c1"}, {"page_print": null, "text": "Водоотдача породы определяется как отношение двух объёмов (по Meinzer, 1923). Первый — объём воды, который порода после насыщения отдаст под действием силы тяжести. Второй — объём самой породы.", "kind": "assumption", "page_pdf": 15, "unit_id": "p015.07", "quote": "The specific yield of a rock is defined as the ratio of (1) the volume of water that the rock, after being saturated, will yield by gravity to (2) its own volume (Meinzer, 1923).", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.specific_yield#c2"}, {"page_print": null, "text": "Водоотдача в сумме с водоудерживающей способностью (specific retention) равна эффективной пористости, то есть учитывает только сообщающиеся поры.", "kind": "assumption", "page_pdf": 16, "unit_id": "p016.01", "quote": "retention equals effective porosity.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Первым слагаемым в этой сумме служит водоотдача.", "quote": "Specific yield plus specific"}, {"text": "Эффективная пористость включает только сообщающиеся поры, способные пропускать флюиды.", "quote": "Effective porosity encompasses only the pore spaces that are interconnected and, therefore, effective in transmitting fluids."}], "id": "keys.specific_yield#c3"}, {"page_print": null, "text": "Мейер (Meyer, 1963) описал применение нейтронного зонда для определения водоотдачи (или коэффициента упругоёмкости, storage coefficient) безнапорного водоносного пласта (unconfined aquifer).", "kind": "observation", "page_pdf": 16, "unit_id": "p016.01", "quote": "Meyer (1963) described the use of a neutron probe to determine the specific yield (or storage coefficient) of an unconfined aquifer.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.specific_yield#c4"}, {"page_print": null, "text": "Джонсон (Johnson, 1967) показал, что водоотдача связана с распределением зёрен по размерам и с пористостью.", "kind": "observation", "page_pdf": 16, "unit_id": "p016.01", "quote": "Johnson (1967) showed that specific yields are related to grain size distribution and porosity.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.specific_yield#c5"}, {"page_print": null, "text": "В общем случае наибольшая водоотдача наблюдается у среднезернистого песка благодаря более однородному распределению зёрен по размерам. Конкретный район или набор пород для этого обобщения не назван.", "kind": "inference", "page_pdf": 16, "unit_id": "p016.01", "quote": "In general, the highest specific yield is found in medium sand because of the more uniform size distribution", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.specific_yield#c6"}, {"page_print": null, "text": "В общем случае наименьшая водоотдача наблюдается у алевритов и глин.", "kind": "observation", "page_pdf": 16, "unit_id": "p016.01", "quote": "In general, the highest specific yield is found in medium sand because of the more uniform size distribution, and the lowest specific yields are found in silts and clays.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.specific_yield#c7"}, {"page_print": null, "text": "Водоотдачу можно оценить по геофизическим каротажным диаграммам.", "kind": "inference", "page_pdf": 16, "unit_id": "p016.01", "quote": "Specific yield can be estimated from geophysical logs.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.specific_yield#c8"}], "id": "keys.specific_yield", "order": 10, "minutes": 3, "essence": "Водоотдача показывает, какую долю объёма породы составляет вода, стекающая из неё под действием тяжести. Вместе с водоудерживающей способностью она равна эффективной пористости. Обычно водоотдача наибольшая у среднезернистого песка, а наименьшая у алевритов и глин.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Породу сначала насыщают водой, то есть заполняют ею поры. Затем вода стекает под действием силы тяжести. Этот процесс называют гравитационным дренированием (gravity drainage).", "pages": [15]}, {"text": "Вытекает не вся вода из сообщающихся пор. Оставшуюся часть описывает водоудерживающая способность (specific retention). Простыми словами, это вода, которую порода удерживает вопреки силе тяжести.", "pages": [16]}, {"text": "Водоотдача и водоудерживающая способность в сумме дают эффективную пористость, то есть долю сообщающихся пор. Джонсон (Johnson, 1967) показал связь водоотдачи с распределением зёрен по размерам и с пористостью. Высокую водоотдачу среднезернистого песка автор объясняет более однородным распределением зёрен по размерам.", "pages": [16]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Водоотдача позволяет сравнивать, насколько разные материалы способны отдавать воду. Сравнение имеет смысл, когда гравитационное дренирование завершилось. По словам автора, поэтому величина очень важна при изучении подземных вод.", "pages": [15]}, {"text": "Её можно оценить по данным геофизического каротажа. Мейер (Meyer, 1963) описал применение нейтронного зонда, то есть скважинного прибора с нейтронным источником. Зондом определяли водоотдачу безнапорного водоносного пласта (unconfined aquifer).", "pages": [16]}, {"text": "Так называют пласт, вода в котором имеет свободную поверхность и не прижата сверху непроницаемым слоем.", "pages": [15, 16]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Водоотдача — отношение объёма отданной воды к объёму самой породы, а не к объёму пор. Рядом с водоотдачей автор в скобках ставит коэффициент упругоёмкости (storage coefficient). Это показатель того, сколько воды пласт отдаёт из запаса при снижении напора.", "pages": [15, 16]}, {"text": "Такое приравнивание дано для безнапорного водоносного пласта. Ряд пород по водоотдаче дан с оговоркой «в общем случае». Чисел водоотдачи для песка, алевритов и глин автор не приводит.", "pages": [16]}, {"text": "Способ расчёта водоотдачи по каротажу здесь тоже не раскрыт.", "pages": [15, 16]}]}], "deeper": [{"text": "Определение водоотдачи автор даёт со ссылкой на Мейнцера (Meinzer, 1923). В табл. 1 главы для водоотдачи безнапорных пластов названы калиброванные нейтронные диаграммы. Алеврит — это осадок с зёрнами мельче песчаных, но крупнее глинистых.", "pages": [15, 16]}], "glossary": [{"term": "водоотдача (specific yield)", "definition": "Отношение объёма воды, который насыщенная порода отдаст под действием силы тяжести, к объёму самой породы."}, {"term": "водоудерживающая способность (specific retention)", "definition": "Характеристика воды, которую порода удерживает вопреки силе тяжести; в сумме с водоотдачей равна эффективной пористости."}, {"term": "гравитационное дренирование (gravity drainage)", "definition": "Стекание воды из пор породы под действием силы тяжести."}, {"term": "безнапорный водоносный пласт (unconfined aquifer)", "definition": "Водоносный пласт, вода в котором имеет свободную поверхность и не прижата сверху непроницаемым слоем."}, {"term": "коэффициент упругоёмкости (storage coefficient)", "definition": "Показатель того, сколько воды пласт отдаёт из запаса или принимает при изменении напора; для безнапорного пласта автор ставит его рядом с водоотдачей как другое название."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [], "numbers": [{"text": "Водоотдача породы определяется как отношение двух объёмов (по Meinzer, 1923). Первый — объём воды, который порода после насыщения отдаст под действием силы тяжести. Второй — объём самой породы.", "page": 15, "claim_id": "keys.specific_yield#c2"}, {"text": "Мейер (Meyer, 1963) описал применение нейтронного зонда для определения водоотдачи (или коэффициента упругоёмкости, storage coefficient) безнапорного водоносного пласта (unconfined aquifer).", "page": 16, "claim_id": "keys.specific_yield#c4"}, {"text": "Джонсон (Johnson, 1967) показал, что водоотдача связана с распределением зёрен по размерам и с пористостью.", "page": 16, "claim_id": "keys.specific_yield#c5"}], "formulas": [], "tables": [], "videos": [], "interactive": null, "narration": null}, {"title": "Сопротивление водонасыщенной породы, пластовой воды и истинное сопротивление — разные величины", "short_title": "Три разных сопротивления: Ro, Rw, Rt", "why_here": {"text": "Вводит обозначения на основе понятия сопротивления породы. Без них нельзя записать формационный фактор.", "by_model": true}, "difficulty": {"primary": "Ф", "secondary": "Н"}, "threshold": true, "pages": [13], "misconception": {"ref": null, "text": "Заблуждение: «у породы с водой есть одно сопротивление, и любое измеренное значение можно называть Ro». На самом деле Ro относится к породе, на 100 процентов насыщенной пластовой водой. Rw относится к самой воде, а истинное сопротивление Rt отличают от Ro из-за поправки на частичное насыщение.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Ro, Rw и Rt — разные обозначения. Ro относится к породе, на 100 процентов насыщенной пластовой водой, Rw — к воде. Истинное сопротивление Rt отличают от Ro.", "by_model": true}, "breaks": {"text": "При частичном насыщении углеводородами нужна поправка, и Rt нельзя без оговорок приравнивать к Ro. То же касалось бы каротажа сопротивления выше уровня грунтовых вод.", "by_model": true}, "hypotheses": [{"text": "В таблице данных Ro, Rw и Rt стоит хранить в отдельных столбцах и не объединять под общим именем «сопротивление».", "by_model": true, "hypothesis": true}, {"text": "Полезно помечать интервалы выше уровня грунтовых вод и интервалы с возможными углеводородами, чтобы не принять их значения за Ro.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Представьте три метрики сервиса. Первая — характеристика отдельного компонента (как Rw). Вторая — эталонный замер всей системы в строго заданном состоянии с этим компонентом (как Ro). Третья — значение, которое отличают от эталона, когда состояние системы может быть другим (как Rt).", "breaks_where": "В ИТ состояние системы часто известно из конфигурации, а метрику снимают напрямую. Для породы насыщение заранее может быть неизвестно, а свойства пластовых флюидов выводят из каротажа косвенно.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Данные каротажа сопротивления и сведения о том, чем и насколько насыщена порода.", "manual_steps": "Различает Ro, Rw и Rt и вводит поправку на частичное насыщение.", "judgment_points": "Решает, полностью ли порода насыщена водой и нужна ли поправка.", "time": "в главе не указано", "typical_errors": "Подмена одной величины другой; пропуск поправки при частичном насыщении.", "by_model": true}, "decision_on_data": {"features": ["Насыщена ли порода пластовой водой на 100 процентов", "Есть ли частичное насыщение углеводородами", "Находится ли интервал каротажа сопротивления выше уровня грунтовых вод"], "rule": "Если порода на 100 процентов насыщена пластовой водой, её сопротивление — это Ro. Если насыщение частичное (углеводороды или интервал выше уровня грунтовых вод), нужна поправка на частичное насыщение.", "conclusion": "Значение сопротивления можно называть Ro только при проверенном полном водонасыщении породы.", "counterexample": "Интервал выше уровня грунтовых вод: нефтяной задачи нет, но поправка на частичное насыщение всё равно понадобилась бы."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["пластовая вода (formation water)", "Ro", "Rw", "Rt", "частичное насыщение углеводородами (partial saturation by hydrocarbons)", "уровень грунтовых вод (water table)"], "links": [{"type": "prerequisite", "target": "keys.resistivity_unit"}, {"type": "prerequisite", "target": "keys.rock_resistivity"}], "needs_scan": [{"page": 14, "what": "Проверить подпись вертикальной оси на рис. 1. По описанию рисунка там сопротивление водоносного пласта обозначено Rt, хотя на стр. 13 Rt отличают от Ro."}], "claims": [{"page_print": null, "text": "Ro — удельное сопротивление породы, на 100 процентов насыщенной пластовой водой (formation water).", "kind": "assumption", "page_pdf": 13, "unit_id": "p013.04", "quote": "The resistivity of a rock that is 100-percent saturated with formation water is $R_{o}$", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.saturated_true_resistivity#c1"}, {"page_print": null, "text": "Rw — удельное сопротивление самой воды; речь о пластовой воде, которой насыщена порода.", "kind": "assumption", "page_pdf": 13, "unit_id": "p013.04", "quote": "and the resistivity of the water is $R_{w}$.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.saturated_true_resistivity#c2"}, {"page_print": null, "text": "Истинное сопротивление (true resistivity), Rt, отличают от Ro — сопротивления породы, на 100 процентов насыщенной пластовой водой.", "kind": "assumption", "page_pdf": 13, "unit_id": "p013.04", "quote": "True resistivity, $R_{t}$, is distinguished from $R_{o}$", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.saturated_true_resistivity#c3"}, {"page_print": null, "text": "Rt отличают от Ro потому, что в разведке нефти необходима поправка на частичное насыщение углеводородами.", "kind": "inference", "page_pdf": 13, "unit_id": "p013.04", "quote": "because correction for partial saturation by hydrocarbons is necessary in petroleum exploration.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.saturated_true_resistivity#c4"}, {"page_print": null, "text": "В гидрогеологии поправка на частичное насыщение тоже понадобилась бы, если бы каротаж сопротивления делали выше уровня грунтовых вод (water table).", "kind": "inference", "page_pdf": 13, "unit_id": "p013.04", "quote": "Correction for partial saturation would also be necessary in hydrology if we made resistivity logs above the water table.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.saturated_true_resistivity#c5"}], "id": "keys.saturated_true_resistivity", "order": 11, "minutes": 2, "essence": "Ro, Rw и Rt обозначают разные сопротивления, поэтому подменять их друг другом нельзя. Ro относится к породе, полностью насыщенной пластовой водой, а Rw относится к самой воде. Истинное сопротивление Rt отличают от Ro из-за поправки на частичное насыщение углеводородами.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Пластовая вода (formation water) — это вода, которая занимает поры породы. Её удельное сопротивление (formation water resistivity) обозначают Rw. Это свойство самой воды, а не породы.", "pages": [13]}, {"text": "Ro описывает уже породу, причём в особом состоянии. Порода должна быть на 100 процентов насыщена пластовой водой. Третья величина — истинное сопротивление (true resistivity), Rt.", "pages": [13]}, {"text": "Автор отличает её от Ro из-за частичного насыщения углеводородами (partial saturation by hydrocarbons). Это случай, когда углеводороды, то есть нефть или газ, насыщают породу частично. Тогда в разведке нефти необходима поправка.", "pages": [13]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Прежде чем считать сопротивление породы величиной Ro, проверьте условие полного насыщения пластовой водой. В разведке нефти приходится учитывать частичное насыщение углеводородами. В гидрогеологии похожая поправка понадобилась бы при каротаже сопротивления выше уровня грунтовых вод (water table).", "pages": [13]}, {"text": "Упрощённо это уровень, ниже которого поры заполнены водой.", "pages": [13]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Прямого определения Rt автор здесь не даёт. Он лишь отличает Rt от Ro и называет причину: поправку на частичное насыщение. Как выполнять эту поправку, в главе не показано.", "pages": [13]}, {"text": "Про гидрогеологию автор говорит условно: поправка понадобилась бы, если бы такой каротаж делали выше уровня грунтовых вод.", "pages": [13]}]}], "deeper": [{"text": "Обозначения Ro и Rw нужны для следующего понятия — формационного фактора (formation resistivity factor). Это отношение сопротивления полностью водонасыщенной породы к сопротивлению насыщающей её воды.", "pages": [13]}], "glossary": [{"term": "пластовая вода (formation water)", "definition": "Вода, которая занимает поры породы в пласте."}, {"term": "Ro", "definition": "Удельное сопротивление породы, на 100 процентов насыщенной пластовой водой."}, {"term": "Rw", "definition": "Удельное сопротивление воды; в этом шаге — пластовой воды, насыщающей породу."}, {"term": "Rt", "definition": "Истинное сопротивление (true resistivity). Его отличают от Ro, поскольку при частичном насыщении нужна поправка."}, {"term": "частичное насыщение углеводородами (partial saturation by hydrocarbons)", "definition": "Состояние, когда нефть или газ насыщают породу частично, а не целиком."}, {"term": "уровень грунтовых вод (water table)", "definition": "Упрощённо: уровень под землёй, ниже которого поры породы заполнены водой."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [{"text": "Проверьте, насыщена ли порода пластовой водой на 100 процентов, прежде чем считать её сопротивление Ro.", "pages": [13], "claim_id": "keys.saturated_true_resistivity#c1"}, {"text": "При разведке нефти введите поправку на частичное насыщение углеводородами и отличайте Rt от Ro.", "pages": [13], "claim_id": "keys.saturated_true_resistivity#c4"}], "numbers": [{"text": "Ro — удельное сопротивление породы, на 100 процентов насыщенной пластовой водой (formation water).", "page": 13, "claim_id": "keys.saturated_true_resistivity#c1"}, {"text": "Истинное сопротивление (true resistivity), Rt, отличают от Ro — сопротивления породы, на 100 процентов насыщенной пластовой водой.", "page": 13, "claim_id": "keys.saturated_true_resistivity#c3"}], "formulas": [], "tables": [], "videos": [], "interactive": null, "narration": null}, {"title": "Формационный фактор связывает сопротивление породы и воды и позволяет найти Rw", "short_title": "Формационный фактор и расчёт Rw", "why_here": {"text": "Опирается на Ro, Rw и эффективную пористость. Нужен для оценки солёности, проницаемости и влияния размера зёрен.", "by_model": true}, "difficulty": {"primary": "Ф", "secondary": "Н"}, "threshold": true, "pages": [14], "misconception": {"ref": "misc.high_res_oil", "text": "Высокое сопротивление само по себе не указывает на нефть. Сопротивление водоносного пласта зависит от пористости и солёности воды. При прочих равных менее пористый пласт с менее солёной водой имеет более высокое сопротивление.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход для расчёта Rw — Ro по каротажу и формационный фактор F; выход — Rw=Ro/F. В слабосцементированных породах F приблизительно связан с эффективной пористостью: F=0,62φ^(−2,15). По каротажным данным о пористости и сопротивлении можно определить солёность поровой воды с помощью рис. 1.", "by_model": false}, "breaks": {"text": "Формула F=Ro/Rw определена для породы, на 100 % насыщенной водой. Связь F с пористостью приблизительна и дана для слабосцементированных пород. Рис. 1 основан на средних значениях для неглинистых зернистых пластов и для конкретного пласта приблизителен.", "by_model": true}, "hypotheses": [{"text": "В формуле F=0,62φ^(−2,15) φ, по-видимому, следует подставлять долей единицы. При подстановке пористости в процентах получилось бы F меньше 1, что противоречит определению свойств F в главе.", "by_model": true, "hypothesis": true}, {"text": "Если сопротивление с каротажа снято в частично водонасыщенном интервале и принято за Ro, расчёт Rw=Ro/F может дать неверное значение.", "by_model": true, "hypothesis": true}, {"text": "Для конкретного водоносного пласта связь F с пористостью, вероятно, стоит проверить по местным образцам и пробам воды.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "F похож на множитель накладных расходов: во сколько раз задержка запроса через сложную сеть больше задержки прямого канала. Зная измеренную задержку и множитель, можно восстановить задержку прямого канала, как Rw=Ro/F.", "breaks_where": "Множитель в ИТ часто задают настройками, а F отражает свойства породы, и по пористости его оценивают лишь приблизительно. Накладные расходы в ИТ также нередко складываются, а F по определению является отношением.", "by_model": true}, "now_practice": {"text": "Такие графические зависимости сегодня обычно заложены в программы интерпретации. Палетка или график остаются способом наглядно проверить расчёт программы.", "by_model": true}, "inefficiency_lens": {"inputs": "Сопротивление Ro и пористость по каротажу, формационный фактор F, график на рис. 1.", "manual_steps": "Вычисляет Rw делением Ro на F и определяет солёность поровой воды по графику.", "judgment_points": "Оценивает, применимы ли средние зависимости к конкретному водоносному пласту.", "time": "в главе не указано", "typical_errors": "Принимать приближённый результат по графику за точный для конкретного пласта.", "by_model": true}, "decision_on_data": {"features": ["Пористость водоносного пласта по каротажу", "Сопротивление водоносного пласта по каротажу", "Пласт зернистый и неглинистый"], "rule": "При прочих равных чем выше пористость и солёность воды, тем ниже сопротивление пласта. По пористости и сопротивлению солёность поровой воды оценивают с помощью рис. 1.", "conclusion": "Если при одинаковой пористости и прочих равных условиях сопротивление одного пласта ниже, вода в нём, вероятно, солонее. Оценка для конкретного пласта приблизительна.", "counterexample": "Два пласта с разным сопротивлением могут содержать одинаково солёную воду, если различается их пористость. Поэтому по одному сопротивлению о солёности судить нельзя."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["формационный фактор (formation resistivity factor)", "F", "слабосцементированные породы (poorly consolidated rocks)"], "links": [{"type": "prerequisite", "target": "keys.saturated_true_resistivity"}, {"type": "prerequisite", "target": "keys.rock_resistivity"}, {"type": "prerequisite", "target": "keys.total_effective_porosity"}, {"type": "refutes_misconception", "target": "misc.high_res_oil"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Зная Ro по каротажным диаграммам и формационный фактор F, можно просто вычислить сопротивление пластовой воды Rw.", "kind": "inference", "page_pdf": 14, "unit_id": "p014.01", "quote": "Using $R_{o}$ from logs and $F$, it is simple to calculate $R_{w}$", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Ro — сопротивление породы, на 100 % насыщенной пластовой водой; Rw — сопротивление этой воды.", "quote": "The resistivity of a rock that is 100-percent saturated with formation water is $R_{o}$, and the resistivity of the water is $R_{w}$."}], "id": "keys.formation_factor#c1"}, {"page_print": null, "text": "Сопротивление воды Rw зависит от температуры и качества воды в водоносном пласте.", "kind": "observation", "page_pdf": 14, "unit_id": "p014.01", "quote": "$R_{w}$, which is a function of the temperature and quality of water in an aquifer:", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.formation_factor#c2"}, {"page_print": null, "text": "Сопротивление пластовой воды вычисляют по формуле Rw=Ro/F.", "kind": "inference", "page_pdf": 14, "unit_id": "p014.02", "quote": "$$\nR_{w}=\\frac{R_{o}}{F}.\n$$", "source_kind": "formula", "by_model": false, "needs_scan": false, "conditions": [{"text": "Ro относится к породе, на 100 % насыщенной пластовой водой.", "quote": "The resistivity of a rock that is 100-percent saturated with formation water is $R_{o}$"}], "id": "keys.formation_factor#c3"}, {"page_print": null, "text": "Формационный фактор F (formation resistivity factor) определяется как отношение удельного электрического сопротивления породы, на 100 % насыщенной водой, к сопротивлению насыщающей её воды: F=Ro/Rw (Archie, 1942).", "kind": "assumption", "page_pdf": 14, "unit_id": "p014.04", "quote": "The formation resistivity factor $(F)$ is defined as the ratio of the electrical resistivity of a rock 100-percent saturated with water to the resistivity of the water with which it is saturated, $F=R_{o}/R_{w}$ (Archie, 1942).", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.formation_factor#c4"}, {"page_print": null, "text": "Поскольку большинство зёрен породы имеют очень высокое сопротивление по сравнению с водой, формационный фактор всегда больше 1.", "kind": "inference", "page_pdf": 14, "unit_id": "p014.04", "quote": "Because most rock grains have a very high resistance relative to water, the formation factor is always greater than 1.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.formation_factor#c5"}, {"page_print": null, "text": "В слабосцементированных породах формационный фактор приблизительно связан с эффективной пористостью зависимостью F=0,62φ^(−2,15).", "kind": "observation", "page_pdf": 14, "unit_id": "p014.04", "quote": "Formation factor is roughly related to effective porosity in poorly consolidated rocks as follows: $F=0.62\\phi^{-2.15}$.", "source_kind": "formula", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.formation_factor#c6"}, {"page_print": null, "text": "Гюйо (Guyod, 1966) показал, как по данным каротажа о пористости и сопротивлении можно определить солёность поровой воды (interstitial water) (рис. 1).", "kind": "observation", "page_pdf": 14, "unit_id": "p014.04", "quote": "Guyod (1966) showed how porosity and resistivity data from logs can be used to determine the salinity of the interstitial water (fig. 1).", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.formation_factor#c7"}, {"page_print": null, "text": "Рис. 1 основан на средних значениях для неглинистых зернистых водоносных пластов, поэтому при применении к конкретному водоносному пласту он приблизителен.", "kind": "assumption", "page_pdf": 14, "unit_id": "p014.04", "quote": "The figure is based on average values for clay-free granular aquifers and is, therefore, approximate when applied to a particular aquifer.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.formation_factor#c8"}, {"page_print": null, "text": "При прочих равных условиях (рис. 1) чем выше пористость и солёность, тем ниже сопротивление водоносного пласта.", "kind": "inference", "page_pdf": 14, "unit_id": "p014.04", "quote": "Thus, if all other factors are equal (fig. 1), the higher the porosity and salinity, the lower the aquifer resistivity.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Рис. 1 построен по средним значениям для неглинистых зернистых водоносных пластов.", "quote": "The figure is based on average values for clay-free granular aquifers"}], "id": "keys.formation_factor#c9"}], "id": "keys.formation_factor", "order": 12, "minutes": 2, "essence": "Формационный фактор F равен сопротивлению водонасыщенной породы Ro, делённому на сопротивление насыщающей воды Rw. Зная Ro по каротажу и F, можно вычислить сопротивление пластовой воды: Rw=Ro/F.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Большинство зёрен породы сопротивляются току очень сильно по сравнению с водой. Поэтому порода, насыщенная водой, имеет большее сопротивление, чем сама эта вода. Отсюда F всегда больше 1.", "pages": [14]}, {"text": "В слабосцементированных породах (poorly consolidated rocks), то есть в породах со слабо скреплёнными зёрнами, F приблизительно связан с эффективной пористостью. Автор даёт зависимость F=0,62φ^(−2,15). Отрицательный показатель степени означает, что с ростом пористости F уменьшается.", "pages": [14]}, {"text": "При прочих равных условиях сопротивление водоносного пласта тем ниже, чем выше пористость и солёность воды.", "pages": [14]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Сопротивление Ro водонасыщенной породы берут из каротажа. Разделив его на F, получают сопротивление пластовой воды Rw (formation water resistivity). Эта величина зависит от температуры и качества воды в водоносном пласте.", "pages": [14]}, {"text": "Гюйо (Guyod, 1966) показал, как по каротажным данным о пористости и сопротивлении определить солёность поровой воды. Поровая вода здесь — вода, находящаяся между зёрнами породы. Для этого служит график на рис.", "pages": [14]}, {"text": "1.", "pages": [14]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Связь F=0,62φ^(−2,15) приблизительная и дана для слабосцементированных пород. Район, раствор и набор данных, по которым она получена, автор не называет. Он также не указывает здесь, подставлять φ долей единицы или процентами.", "pages": [14]}, {"text": "Рис. 1 построен по средним значениям для неглинистых зернистых водоносных пластов. Поэтому для конкретного пласта он даёт лишь приближённый результат.", "pages": [14]}, {"text": "Определение F и расчёт Rw=Ro/F относятся к породе, на 100 % насыщенной водой.", "pages": [14]}]}], "deeper": [], "glossary": [{"term": "формационный фактор (formation resistivity factor)", "definition": "Отношение удельного электрического сопротивления породы, на 100 % насыщенной водой, к сопротивлению этой воды."}, {"term": "F", "definition": "Обозначение формационного фактора: F=Ro/Rw; по главе, он всегда больше 1."}, {"term": "слабосцементированные породы (poorly consolidated rocks)", "definition": "Породы, зёрна которых слабо скреплены между собой; для них автор даёт приближённую связь F с эффективной пористостью."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [{"text": "Возьмите по каротажным диаграммам сопротивление Ro породы, на 100 процентов насыщенной водой.", "pages": [14], "claim_id": "keys.formation_factor#c1"}, {"text": "Разделите Ro на формационный фактор F и получите сопротивление пластовой воды Rw.", "pages": [14], "claim_id": "keys.formation_factor#c3"}, {"text": "Чтобы найти солёность поровой воды, используйте данные о пористости и сопротивлении и график на рис. 1.", "pages": [14], "claim_id": "keys.formation_factor#c7"}, {"text": "Считайте результат по графику приблизительным: он построен по средним значениям для неглинистых зернистых пластов.", "pages": [14], "claim_id": "keys.formation_factor#c8"}], "numbers": [{"text": "Формационный фактор F (formation resistivity factor) определяется как отношение удельного электрического сопротивления породы, на 100 % насыщенной водой, к сопротивлению насыщающей её воды: F=Ro/Rw (Archie, 1942).", "page": 14, "claim_id": "keys.formation_factor#c4"}, {"text": "Поскольку большинство зёрен породы имеют очень высокое сопротивление по сравнению с водой, формационный фактор всегда больше 1.", "page": 14, "claim_id": "keys.formation_factor#c5"}, {"text": "В слабосцементированных породах формационный фактор приблизительно связан с эффективной пористостью зависимостью F=0,62φ^(−2,15).", "page": 14, "claim_id": "keys.formation_factor#c6"}, {"text": "Гюйо (Guyod, 1966) показал, как по данным каротажа о пористости и сопротивлении можно определить солёность поровой воды (interstitial water) (рис. 1).", "page": 14, "claim_id": "keys.formation_factor#c7"}], "formulas": [{"tex": "F=\\frac{R_{o}}{R_{w}}", "page": 14, "claim_id": "keys.formation_factor#c4", "legend": [{"symbol": "F", "meaning": "формационный фактор", "unit": ""}, {"symbol": "R_{o}", "meaning": "удельное сопротивление породы, на 100 % насыщенной водой", "unit": ""}, {"symbol": "R_{w}", "meaning": "удельное сопротивление насыщающей воды", "unit": ""}], "errata": null}, {"tex": "R_{w}=\\frac{R_{o}}{F}", "page": 14, "claim_id": "keys.formation_factor#c3", "legend": [{"symbol": "R_{w}", "meaning": "удельное сопротивление пластовой воды", "unit": ""}, {"symbol": "R_{o}", "meaning": "удельное сопротивление водонасыщенной породы", "unit": ""}, {"symbol": "F", "meaning": "формационный фактор", "unit": ""}], "errata": null}, {"tex": "F=0.62\\phi^{-2.15}", "page": 14, "claim_id": "keys.formation_factor#c6", "legend": [{"symbol": "F", "meaning": "формационный фактор в слабосцементированных породах (приближённо)", "unit": ""}, {"symbol": "\\phi", "meaning": "эффективная пористость", "unit": ""}], "errata": null}], "tables": [], "videos": [], "interactive": null, "narration": null}, {"title": "Сопротивление раствора зависит от концентрации соли и температуры", "short_title": "Как по сопротивлению воды оценить солёность", "why_here": {"text": "После расчёта Rw показывает, как по нему и температуре оценить минерализацию. Готовит пересчёт других ионов и палетку для водоносных пластов.", "by_model": true}, "difficulty": {"primary": "И", "secondary": "Пр"}, "threshold": true, "pages": [16, 17], "misconception": {"ref": null, "text": "Кажется, что по одному сопротивлению воды можно сразу назвать её солёность и состав. На деле нужна ещё температура. График даёт лишь эквивалент NaCl, а не сам химический состав.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Входы: сопротивление или проводимость жидкости и её температура. Выход: приближённое общее электрически эквивалентное содержание NaCl в мг/л по рис. 2. При других ионах входом для пересчёта служат их концентрации и множители. Если состав известен по анализам и соотношения ионов устойчивы, по каротажу можно приближённо оценить количества ионов.", "by_model": true}, "breaks": {"text": "Переводные множители меняются с концентрацией. Для концентраций выше 100000 ppm Desai и Moore предложили более точный метод. Оценка отдельных ионов требует анализов и устойчивых соотношений ионов. Жидкость в скважине можно сопоставлять с водой пласта лишь при равновесии, гидравлической связи и ненарушающем их течении в стволе.", "by_model": true}, "hypotheses": [{"text": "В таблице данных стоит хранить рядом с каждым значением сопротивления температуру измерения, иначе значения трудно сравнивать.", "by_model": true, "hypothesis": true}, {"text": "Единицы мг/л и ppm стоит хранить явно и не считать взаимозаменяемыми без проверки плотности раствора.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Пересчёт ионов в эквивалент NaCl похож на приведение разных метрик к одной условной единице с весами. Каждый вклад умножают на свой коэффициент и складывают, а дальше работают с одним числом.", "breaks_where": "Веса здесь не постоянные константы: они меняются с концентрацией. Кроме того, из суммы нельзя восстановить состав без анализов и устойчивых соотношений ионов. Связь с сопротивлением ещё и зависит от температуры.", "by_model": true}, "now_practice": {"text": "Сейчас те же зависимости обычно заложены в программы интерпретации. График остаётся способом наглядно проверить результат программы.", "by_model": true}, "inefficiency_lens": {"inputs": "Сопротивление или проводимость воды, температура, при наличии других ионов — их концентрации из химических анализов.", "manual_steps": "Умножить концентрацию каждого иона на множитель, сложить произведения, затем найти точку на графике по температуре и концентрации или сопротивлению.", "judgment_points": "Устойчивы ли соотношения ионов; применимы ли множители при данной концентрации; отражает ли жидкость в скважине воду пласта.", "time": "в главе не указано", "typical_errors": "Возможные ошибки: перепутать °F и °C, сопротивление и проводимость, неточно снять значение с логарифмической шкалы, забыть про температуру.", "by_model": true}, "decision_on_data": {"features": ["Сопротивление или проводимость жидкости", "Температура жидкости", "Концентрации других ионов по химическим анализам", "Устойчивость соотношений ионов"], "rule": "Если известны сопротивление или проводимость и температура, по рис. 2 приближённо находят эквивалент NaCl. Другие ионы переводят в этот эквивалент умножением на множители и сложением. Количества ионов по каротажу оценивают, только если состав известен по анализам и соотношения устойчивы.", "conclusion": "Получают приближённое эквивалентное содержание NaCl, а при выполненных условиях — приближённые количества ионов.", "counterexample": "Раствор с 1000 мг/л Ca⁺² и 2400 мг/л SO₄⁻² электрически эквивалентен 2150 мг/л NaCl. Значит, один лишь электрический отклик не говорит, что в воде именно хлорид натрия."}, "worked_examples": [{"page_pdf": 16, "condition": "Раствор содержит 1000 мг/л Ca⁺² и 2400 мг/л SO₄⁻². Нужно найти эквивалентную концентрацию NaCl и сопротивление такой воды при 50 °F (10 °C).", "steps": ["Берут множители: для Ca⁺² — 0,95, для SO₄⁻² — 0,50.", "Считают: 1000 × 0,95 + 2400 × 0,50 = 2150 мг/л эквивалентного раствора NaCl.", "По рис. 2 находят сопротивление воды с CaSO₄ при 50 °F (10 °C)."], "result": "Эквивалент — 2150 мг/л NaCl; сопротивление — около 3,5 Ом·м (2860 мкмо/см).", "figure": "рис. 2"}], "book_tasks": [], "terms_introduced": ["удельная электропроводность (conductivity)", "мкмо/см (μmhos/cm)", "мг/л (mg/l)", "миллионные доли (ppm)", "хлорид натрия (NaCl)"], "links": [{"type": "prerequisite", "target": "keys.resistivity_unit"}, {"type": "prerequisite", "target": "keys.rock_resistivity"}, {"type": "prerequisite", "target": "keys.saturated_true_resistivity"}, {"type": "prerequisite", "target": "keys.formation_factor"}], "needs_scan": [{"page": 17, "what": "Рис. 2: сверить по скану оси, диапазоны шкал, подписи линий концентрации и направление их наклона."}, {"page": 17, "what": "Рис. 2: проверить по графику значение из примера — около 3,5 Ом·м при 50 °F (10 °C) для 2150 мг/л NaCl."}], "claims": [{"page_print": null, "text": "По оценке авторов, проводимость или сопротивление (Rw) жидкости в стволе скважины или водоносном пласте — один из самых полезных для гидрогеологии параметров, получаемых по геофизическому каротажу.", "kind": "inference", "page_pdf": 16, "unit_id": "p016.07", "quote": "The conductivity or resistivity $(R_{w})$ of fluid in a well bore or aquifer is one of the most useful ground-water factors that can be derived from geophysical logs.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.fluid_conductivity_chart#c1"}, {"page_print": null, "text": "В большей части каротажа нефтяных скважин используют сопротивление жидкости, а не обратную ему величину — проводимость.", "kind": "observation", "page_pdf": 16, "unit_id": "p016.07", "quote": "Fluid resistivity, rather than the reciprocal conductivity, is used for most oil-well logging.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.fluid_conductivity_chart#c2"}, {"page_print": null, "text": "Рис. 2 — график для растворов NaCl, существенно переработанный вариант графика, опубликованного Schlumberger Well Surveying Corp. (Alger, 1966).", "kind": "observation", "page_pdf": 16, "unit_id": "p016.07", "quote": "Figure 2 is a graph for NaCl solutions, considerably modified from one published by the Schlumberger Well Surveying Corp. (Alger, 1966).", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.fluid_conductivity_chart#c3"}, {"page_print": null, "text": "Чтобы график был полезнее гидрогеологам, его расширили на более широкий диапазон солёности, а также на более низкие температуры и проводимость, и добавили шкалы Цельсия.", "kind": "observation", "page_pdf": 16, "unit_id": "p016.07", "quote": "To make the chart more useful to ground-water hydrologists, it was extended to cover a wider range of salinities, as well as lower temperatures and conductivity, and Celsius temperature scales were added.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.fluid_conductivity_chart#c4"}, {"page_print": null, "text": "Если известны и сопротивление или проводимость жидкости, и её температура, по графику можно приближённо определить общее электрически эквивалентное содержание NaCl в мг/л.", "kind": "inference", "page_pdf": 16, "unit_id": "p016.07", "quote": "If both the resistivity or conductivity of the fluid and the fluid temperature are known, then the total electrically equivalent NaCl, in milligrams per liter (mg/l), can be approximated from this graph.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.fluid_conductivity_chart#c5"}, {"page_print": null, "text": "На момент написания книги вся коммерческая каротажная аппаратура и литература по каротажу всё ещё использовали градусы Фаренгейта и миллионные доли (ppm).", "kind": "observation", "page_pdf": 16, "unit_id": "p016.07", "quote": "(At the present time all commercial logging equipment and logging literature still use Fahrenheit and parts per million.)", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.fluid_conductivity_chart#c6"}, {"page_print": null, "text": "Если в воде присутствуют другие ионы, для перевода в электрически эквивалентную концентрацию NaCl можно использовать множители (Lynch, 1962): Ca⁺² — 0,95; Mg⁺² — 2,00; K⁺¹ — 1,00; SO₄⁻² — 0,50; HCO₃⁻¹ — 0,27; CO₃⁻² — 1,26.", "kind": "assumption", "page_pdf": 16, "unit_id": "p016.07", "quote": "converting to electrically equivalent sodium chloride concentrations: $\\mathrm{Ca}^{+2}=0.95$, $\\mathrm{Mg}^{+2}=2.00$, $\\mathrm{K}^{+1}=1.00$, $\\mathrm{SO}_{4}^{-2}=0.50$, $\\mathrm{HCO}_{3}^{-1}=0.27$, and $\\mathrm{CO}_{3}^{-2}=1.26$", "source_kind": "formula", "by_model": false, "needs_scan": false, "conditions": [{"text": "Множители применяют, когда присутствуют другие ионы.", "quote": "If other ions are present, the following multiplying factors can be used"}], "id": "keys.fluid_conductivity_chart#c7"}, {"page_print": null, "text": "Если химический состав воды водоносного пласта известен по анализам и соотношения ионов устойчивы, по сопротивлению или проводимости из каротажа можно определить приближённые количества этих ионов.", "kind": "inference", "page_pdf": 16, "unit_id": "p016.07", "quote": "Thus, if the chemical nature of water in an aquifer is known from chemical analyses, and the ratios of ions are consistent, resistivity or conductivity from logs can be used to determine the approximate quantities of those ions present.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.fluid_conductivity_chart#c8"}, {"page_print": null, "text": "Пример: раствор с 1000 мг/л Ca⁺² и 2400 мг/л SO₄⁻² электрически эквивалентен раствору с 2150 мг/л NaCl.", "kind": "inference", "page_pdf": 16, "unit_id": "p016.07", "quote": "For example, a solution containing 1,000 mg/l $\\mathrm{Ca}^{+2}$ and 2,400 mg/l $\\mathrm{SO}_{4}^{-2}$ would be electrically equivalent to a solution with 2,150 mg/l NaCl", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.fluid_conductivity_chart#c9"}, {"page_print": null, "text": "Эквивалент в примере считают так: 1000 × 0,95 + 2400 × 0,50 = 2150 мг/л эквивалентного раствора NaCl.", "kind": "inference", "page_pdf": 16, "unit_id": "p016.07", "quote": "calculated as follows: $1,000 \\times 0.95+2,400 \\times 0.50=2,150$ mg/l equivalent NaCl solution.", "source_kind": "formula", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.fluid_conductivity_chart#c10"}, {"page_print": null, "text": "По рис. 2 сопротивление воды с CaSO₄ из примера при 50 °F (10 °C) составило бы около 3,5 Ом·м (2860 мкмо/см).", "kind": "inference", "page_pdf": 16, "unit_id": "p016.07", "quote": "Thus, according to figure 2, the resistivity of the $\\mathrm{CaSO}_{4}$ water at 50° F (10°C) would be about 3.5 ohm-meters (2,860 $\\mu$mhos/cm).", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [{"text": "Речь о растворе с 1000 мг/л Ca⁺² и 2400 мг/л SO₄⁻².", "quote": "a solution containing 1,000 mg/l $\\mathrm{Ca}^{+2}$ and 2,400 mg/l $\\mathrm{SO}_{4}^{-2}$"}], "id": "keys.fluid_conductivity_chart#c11"}, {"page_print": null, "text": "Desai и Moore (1969) показали, что приведённые переводные множители меняются в зависимости от концентрации.", "kind": "observation", "page_pdf": 16, "unit_id": "p016.07", "quote": "Desai and Moore (1969) showed that the above conversion factors vary according to concentration", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.fluid_conductivity_chart#c12"}, {"page_print": null, "text": "Desai и Moore представили более точный метод для растворённых веществ при концентрациях выше 100000 ppm.", "kind": "observation", "page_pdf": 16, "unit_id": "p016.07", "quote": "they presented a more accurate method for dissolved solids in concentrations greater than 100,000 ppm.", "source_kind": "text", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.fluid_conductivity_chart#c13"}, {"page_print": null, "text": "Рис. 2 показывает электрически эквивалентные концентрации раствора хлорида натрия в зависимости от сопротивления или проводимости и температуры.", "kind": "observation", "page_pdf": 17, "unit_id": "p017.02", "quote": "Figure 2. — Electrically equivalent concentrations of a sodium chloride solution as a function of resistivity or conductivity and temperature.", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "conditions": [], "id": "keys.fluid_conductivity_chart#c14"}, {"page_print": null, "text": "На верхней горизонтальной оси рис. 2 отложено удельное сопротивление в Ом·м по логарифмической шкале с отметками от 0,3 до 200.", "kind": "observation", "page_pdf": 17, "unit_id": "p017.01", "quote": "- Верхняя ось X: RESISTIVITY — ohm-meters (удельное сопротивление, Ом·м), логарифмическая шкала, подписаны отметки .3, .5, 1, 2, 5, 10, 20, 50, 100, 200.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "conditions": [], "id": "keys.fluid_conductivity_chart#c15"}, {"page_print": null, "text": "На нижней горизонтальной оси рис. 2 отложена удельная электропроводность в мкмо/см по логарифмической шкале; значения от 20000 до 50 убывают слева направо.", "kind": "observation", "page_pdf": 17, "unit_id": "p017.01", "quote": "- Нижняя ось X: CONDUCTIVITY — μmhos/cm (удельная электропроводность, мкмо/см), логарифмическая шкала, подписаны отметки 20000, 10000, 5000, 2000, 1000, 500, 200, 100, 50; значения убывают слева направо.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "conditions": [], "id": "keys.fluid_conductivity_chart#c16"}, {"page_print": null, "text": "По вертикали на рис. 2 отложена температура: слева от 5 до 60 °C, справа от 35 до 140 °F; значения растут вниз.", "kind": "observation", "page_pdf": 17, "unit_id": "p017.01", "quote": "- Левая ось Y: TEMPERATURE, DEGREES CELSIUS — от 5 до 60 °C, значения возрастают вниз.\n- Правая ось Y: TEMPERATURE, DEGREES FAHRENHEIT — от 35 до 140 °F, значения возрастают вниз.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "conditions": [], "id": "keys.fluid_conductivity_chart#c17"}, {"page_print": null, "text": "На поле рис. 2 проведены наклонные прямые равной концентрации NaCl с подписями от 50 до 10000 мг/л.", "kind": "observation", "page_pdf": 17, "unit_id": "p017.01", "quote": "На поле графика — семейство наклонных прямых равной концентрации раствора NaCl, подписи у линий (мг/л NaCl): 10000, 8000, 6000, 5000, 4000, 3000, 2000, 1500, 1000, 800, 600, 500, 400, 300, 200, 150, 100, 50.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "conditions": [], "id": "keys.fluid_conductivity_chart#c18"}, {"page_print": null, "text": "По рис. 2 при постоянной концентрации сопротивление раствора NaCl падает с ростом температуры.", "kind": "observation", "page_pdf": 17, "unit_id": "p017.01", "quote": "Качественное поведение: при постоянной концентрации удельное сопротивление раствора падает с ростом температуры (прямые наклонены влево вниз);", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "conditions": [], "id": "keys.fluid_conductivity_chart#c19"}, {"page_print": null, "text": "По рис. 2 при постоянной температуре чем выше концентрация, тем ниже сопротивление раствора и выше его проводимость.", "kind": "observation", "page_pdf": 17, "unit_id": "p017.01", "quote": "при постоянной температуре чем выше концентрация, тем ниже сопротивление и выше проводимость.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "conditions": [], "id": "keys.fluid_conductivity_chart#c20"}, {"page_print": null, "text": "Отдельные точки на рис. 2 не нанесены; значения снимают с линий приближённо.", "kind": "observation", "page_pdf": 17, "unit_id": "p017.01", "quote": "Отдельные точки не нанесены, значения снимаются с линий (приблизительно).", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "conditions": [], "id": "keys.fluid_conductivity_chart#c21"}], "id": "keys.fluid_conductivity_chart", "order": 13, "minutes": 5, "essence": "По сопротивлению или проводимости раствора и его температуре можно приближённо найти содержание соли. График даёт его как электрически эквивалентную концентрацию хлорида натрия (NaCl). Другие ионы переводят в этот эквивалент множителями, которые меняются с концентрацией.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Удельная электропроводность (conductivity) показывает, насколько хорошо вещество проводит ток. Это величина, обратная удельному электрическому сопротивлению (resistivity). Её здесь выражают в мкмо/см (μmhos/cm), то есть микромо на сантиметр; «мо» — единица, обратная ому.", "pages": [16, 17]}, {"text": "Сопротивление воды выражают в ом-метрах. Сопротивление раствора связано с двумя величинами: концентрацией соли и температурой. На рис.", "pages": [17]}, {"text": "2 при одной температуре более концентрированный раствор имеет меньшее сопротивление и большую проводимость. При одной концентрации сопротивление падает с ростом температуры. График построен для растворов хлорида натрия (NaCl), то есть обычной поваренной соли.", "pages": [17]}, {"text": "Концентрацию указывают в мг/л (mg/l) — миллиграммах вещества на литр раствора. Природная вода может содержать и другие ионы, то есть заряженные частицы растворённых веществ. Их переводят в электрически эквивалентный NaCl.", "pages": [16]}, {"text": "Это такое количество NaCl, которое по электрическим свойствам заменяет данную смесь. Концентрацию каждого иона умножают на его множитель, а произведения складывают.", "pages": [16]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Чтобы пользоваться графиком, нужны две величины: сопротивление или проводимость воды и её температура. По ним приближённо снимают общее эквивалентное содержание NaCl. Множители авторы приводят по Lynch (1962): Ca⁺² — 0,95; Mg⁺² — 2,00; K⁺¹ — 1,00; SO₄⁻² — 0,50; HCO₃⁻¹ — 0,27; CO₃⁻² — 1,26.", "pages": [16]}, {"text": "Пример авторов: в растворе 1000 мг/л Ca⁺² и 2400 мг/л SO₄⁻². Расчёт даёт 1000·0,95 + 2400·0,50 = 2150 мг/л эквивалентного NaCl. По рис.", "pages": [16]}, {"text": "2 сопротивление такой воды при 50 °F (10 °C) — около 3,5 Ом·м (2860 мкмо/см). Возможен и обратный ход. Пусть состав воды пласта известен по химическим анализам, а соотношения ионов устойчивы.", "pages": [16]}, {"text": "Тогда по сопротивлению или проводимости из каротажа можно приближённо оценить количества этих ионов.", "pages": [16]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Результат, снятый с графика, приближённый. Для приведённых множителей авторы в этом месте не называют пород, района или диапазона концентраций. При этом они ссылаются на Desai и Moore (1969): множители меняются с концентрацией.", "pages": [16]}, {"text": "Для растворённых веществ при концентрациях выше 100000 миллионных долей (ppm) те предложили более точный метод. Миллионные доли (ppm) — число частей вещества на миллион частей раствора. Авторы отмечают, что на момент написания коммерческая аппаратура и литература по каротажу использовали ppm и градусы Фаренгейта.", "pages": [16]}, {"text": "Сам график переведён на мг/л и дополнен шкалой Цельсия. Подписанные линии рис. 2 охватывают от 50 до 10000 мг/л NaCl.", "pages": [16, 17]}, {"text": "Значения между линиями и по осям читаются лишь приближённо. Вода в скважине не обязательно отражает воду пласта. В другом месте главы для такого сопоставления названы условия.", "pages": [16, 17]}, {"text": "Скважина должна прийти в химическое и тепловое равновесие с пластом и иметь с ним достаточную гидравлическую связь. Течение внутри ствола не должно нарушать эти условия.", "pages": [16, 17]}]}], "deeper": [{"text": "Rw в этой главе обозначает сопротивление или, шире, электрическую характеристику воды в стволе или водоносном пласте. Для большей части каротажа нефтяных скважин используют именно сопротивление, а не обратную ему проводимость.\n\nРис. 2 — существенно переработанный график фирмы Schlumberger Well Surveying Corp. (Alger, 1966). Его расширили для гидрогеологов: больше диапазон солёности, ниже температуры и проводимость, добавлена шкала Цельсия.\n\nОбе горизонтальные шкалы графика логарифмические. Сопротивление отложено сверху, проводимость снизу и убывает слева направо. Температура растёт вниз: слева в °C, справа в °F.", "pages": [16]}], "glossary": [{"term": "удельная электропроводность (conductivity)", "definition": "Способность вещества проводить электрический ток; величина, обратная удельному электрическому сопротивлению."}, {"term": "мкмо/см (μmhos/cm)", "definition": "Единица удельной электропроводности: микромо на сантиметр, где «мо» — единица, обратная ому."}, {"term": "мг/л (mg/l)", "definition": "Концентрация: миллиграммы растворённого вещества в литре раствора."}, {"term": "миллионные доли (ppm)", "definition": "Концентрация: число частей вещества на миллион частей раствора."}, {"term": "хлорид натрия (NaCl)", "definition": "Поваренная соль; растворы NaCl служат эталоном, к которому приводят электрические свойства воды с другими ионами."}], "format": null, "format_why": null, "tasks": [], "pictures": [], "procedure": [{"text": "Определите сопротивление или проводимость жидкости и её температуру: для работы с графиком нужны обе величины.", "pages": [16], "claim_id": "keys.fluid_conductivity_chart#c5"}, {"text": "Снимите по рис. 2 приближённое общее эквивалентное содержание NaCl в мг/л.", "pages": [16], "claim_id": "keys.fluid_conductivity_chart#c5"}, {"text": "Если известны концентрации других ионов, умножьте каждую на её множитель и сложите произведения.", "pages": [16], "claim_id": "keys.fluid_conductivity_chart#c7"}, {"text": "По эквивалентной концентрации NaCl и температуре найдите по рис. 2 сопротивление или проводимость воды.", "pages": [16], "claim_id": "keys.fluid_conductivity_chart#c11"}, {"text": "При концентрациях растворённых веществ выше 100000 ppm используйте более точный метод Desai и Moore.", "pages": [16], "claim_id": "keys.fluid_conductivity_chart#c13"}, {"text": "Если состав воды известен и соотношения ионов устойчивы, оцените по каротажному сопротивлению количества этих ионов.", "pages": [16], "claim_id": "keys.fluid_conductivity_chart#c8"}], "numbers": [{"text": "Рис. 2 — график для растворов NaCl, существенно переработанный вариант графика, опубликованного Schlumberger Well Surveying Corp. (Alger, 1966).", "page": 16, "claim_id": "keys.fluid_conductivity_chart#c3"}, {"text": "Если в воде присутствуют другие ионы, для перевода в электрически эквивалентную концентрацию NaCl можно использовать множители (Lynch, 1962): Ca⁺² — 0,95; Mg⁺² — 2,00; K⁺¹ — 1,00; SO₄⁻² — 0,50; HCO₃⁻¹ — 0,27; CO₃⁻² — 1,26.", "page": 16, "claim_id": "keys.fluid_conductivity_chart#c7"}, {"text": "Пример: раствор с 1000 мг/л Ca⁺² и 2400 мг/л SO₄⁻² электрически эквивалентен раствору с 2150 мг/л NaCl.", "page": 16, "claim_id": "keys.fluid_conductivity_chart#c9"}, {"text": "Эквивалент в примере считают так: 1000 × 0,95 + 2400 × 0,50 = 2150 мг/л эквивалентного раствора NaCl.", "page": 16, "claim_id": "keys.fluid_conductivity_chart#c10"}, {"text": "По рис. 2 сопротивление воды с CaSO₄ из примера при 50 °F (10 °C) составило бы около 3,5 Ом·м (2860 мкмо/см).", "page": 16, "claim_id": "keys.fluid_conductivity_chart#c11"}, {"text": "Desai и Moore (1969) показали, что приведённые переводные множители меняются в зависимости от концентрации.", "page": 16, "claim_id": "keys.fluid_conductivity_chart#c12"}, {"text": "Desai и Moore представили более точный метод для растворённых веществ при концентрациях выше 100000 ppm.", "page": 16, "claim_id": "keys.fluid_conductivity_chart#c13"}, {"text": "На верхней горизонтальной оси рис. 2 отложено удельное сопротивление в Ом·м по логарифмической шкале с отметками от 0,3 до 200.", "page": 17, "claim_id": "keys.fluid_conductivity_chart#c15"}, {"text": "На нижней горизонтальной оси рис. 2 отложена удельная электропроводность в мкмо/см по логарифмической шкале; значения от 20000 до 50 убывают слева направо.", "page": 17, "claim_id": "keys.fluid_conductivity_chart#c16"}, {"text": "По вертикали на рис. 2 отложена температура: слева от 5 до 60 °C, справа от 35 до 140 °F; значения растут вниз.", "page": 17, "claim_id": "keys.fluid_conductivity_chart#c17"}, {"text": "На поле рис. 2 проведены наклонные прямые равной концентрации NaCl с подписями от 50 до 10000 мг/л.", "page": 17, "claim_id": "keys.fluid_conductivity_chart#c18"}], "formulas": [{"tex": "1000 \\times 0,95 + 2400 \\times 0,50 = 2150", "page": 16, "claim_id": "keys.fluid_conductivity_chart#c10", "legend": [{"symbol": "1000", "meaning": "концентрация ионов Ca⁺² в растворе из примера", "unit": "мг/л"}, {"symbol": "0,95", "meaning": "множитель перевода Ca⁺² в эквивалент NaCl", "unit": ""}, {"symbol": "2400", "meaning": "концентрация ионов SO₄⁻² в растворе из примера", "unit": "мг/л"}, {"symbol": "0,50", "meaning": "множитель перевода SO₄⁻² в эквивалент NaCl", "unit": ""}, {"symbol": "2150", "meaning": "электрически эквивалентная концентрация NaCl", "unit": "мг/л"}], "errata": null}], "tables": [], "videos": [], "interactive": null, "narration": null}]};
